COMPENDIUM.parts[2] = /*JSON-START*/{
  "part": 3, "slug": "mesihte-yasam", "tr": "Mesih'te Yaşam", "en": "Life in Christ", "from": 357, "to": 533,
  "items": [
    { "type": "heading", "level": 1, "id": "ucuncu-kisim-mesihte-yasam",
      "tr": "Üçüncü Kısım: Mesih'te Yaşam",
      "en": "Part Three: Life in Christ" },
    { "type": "heading", "level": 2, "id": "birinci-bolum-insanin-cagrisi-ruhta-yasam",
      "tr": "Birinci Bölüm: İnsanın Çağrısı – Ruh'ta Yaşam",
      "en": "Section One: Man's Vocation: Life in the Spirit" },
    { "type": "qa", "n": 357, "id": "soru-357", "ccc": "1691–1698",
      "tr": { "q": "Hristiyan ahlaki yaşamı iman ve kutsal sırlarla nasıl bağlantılıdır?",
              "a": "İmanın simgesinin ikrar ettiğini kutsal sırlar iletir. Gerçekten de inanlılar, kutsal sırlar aracılığıyla, imanla kabul ettikleri Mesih'te Tanrı'nın çocukları olarak yeni bir yaşam sürme yeteneğini onlara veren Mesih'in lütfunu ve Kutsal Ruh'un armağanlarını alırlar." },
      "en": { "q": "How is the Christian moral life bound up with faith and the sacraments?",
              "a": "What the symbol of faith professes, the sacraments communicate. Indeed, through them the faithful receive the grace of Christ and the gifts of the Holy Spirit which give them the capability of living a new life as children of God in Christ whom they have received in faith." } },
    { "type": "quote",
      "tr": "“Ey Hristiyan, onurunu tanı!” ([[Büyük Aziz Leo|Saint Leo the Great]])",
      "en": "“O Christian, recognize your dignity.”  (Saint Leo the Great)" },
    { "type": "heading", "level": 3, "id": "birinci-baslik-insan-kisisinin-onuru",
      "tr": "Birinci Başlık: İnsan Kişisinin Onuru",
      "en": "Chapter One: The Dignity of the Human Person" },
    { "type": "heading", "level": 4, "id": "tanrinin-sureti-olarak-insan",
      "tr": "Tanrı'nın Sureti Olarak İnsan",
      "en": "Man the Image of God" },
    { "type": "qa", "n": 358, "id": "soru-358", "ccc": "1699–1715",
      "tr": { "q": "İnsan onurunun kökü nedir?",
              "a": "İnsan kişisinin onuru, onun Tanrı'nın suretinde ve benzerliğinde yaratılmış olmasına dayanır. Ruhsal ve ölümsüz bir can, akıl ve özgür iradeyle donatılmış olan insan kişisi Tanrı'ya yöneliktir ve canıyla ve bedeniyle sonsuz mutluluğa çağrılmıştır." },
      "en": { "q": "What is the root of human dignity?",
              "a": "The dignity of the human person is rooted in his or her creation in the image and likeness of God. Endowed with a spiritual and immortal soul, intelligence and free will, the human person is ordered to God and called in soul and in body to eternal beatitude." } },
    { "type": "heading", "level": 4, "id": "mutluluga-cagrimiz",
      "tr": "Mutluluğa Çağrımız",
      "en": "Our Vocation to Beatitude" },
    { "type": "qa", "n": 359, "id": "soru-359", "ccc": "1716",
      "tr": { "q": "Mutluluğa nasıl ulaşırız?",
              "a": "Mutluluğa, bizi tanrısal yaşama ortak kılan Mesih'in lütfu sayesinde ulaşırız. Mesih İncil'de izleyicilerine sonsuz mutluluğa götüren yolu gösterir: Mutluluk Çağrıları (Sekiz Mutluluk). Mesih'in lütfu, doğru bir vicdanı izleyerek gerçeği ve iyiyi arayan ve seven ve kötülükten kaçınan her insanda da etkindir." },
      "en": { "q": "How do we attain beatitude?",
              "a": "We attain beatitude by virtue of the grace of Christ which makes us participants in the divine life. Christ in the Gospel points out to his followers the way that leads to eternal happiness: the beatitudes. The grace of Christ also is operative in every person who, following a correct conscience, seeks and loves the true and the good and avoids evil." } },
    { "type": "qa", "n": 360, "id": "soru-360", "ccc": "1716–1717, 1725–1726",
      "tr": { "q": "Mutluluk Çağrıları bizim için neden önemlidir?",
              "a": "Mutluluk Çağrıları İsa'nın vaazının kalbindedir; Tanrı'nın [[İbrahim'le|Abraham]] başlayarak verdiği vaatleri üstlenir ve tamamlar. İsa'nın çehresinin ta kendisini betimler ve sahih Hristiyan yaşamını belirginleştirir. İnsan etkinliğinin nihai amacını, yani sonsuz mutluluğu açıklar." },
      "en": { "q": "Why are the beatitudes important for us?",
              "a": "The beatitudes are at the heart of Jesus’ preaching and they take up and fulfill the promises that God made starting with Abraham. They depict the very countenance of Jesus and they characterize authentic Christian life. They reveal the ultimate goal of human activity, which is eternal happiness." } },
    { "type": "qa", "n": 361, "id": "soru-361", "ccc": "1718–1719",
      "tr": { "q": "Mutluluk Çağrıları ile mutluluk arzumuz arasındaki ilişki nedir?",
              "a": "Mutluluk Çağrıları, Tanrı'nın bizi Kendine çekmek için insan yüreğine yerleştirdiği doğuştan mutluluk arzusuna yanıt verir. Bu arzuyu yalnızca Tanrı doyurabilir." },
      "en": { "q": "What is the relationship between the beatitudes and our desire for happiness?",
              "a": "The beatitudes respond to the innate desire for happiness that God has placed in the human heart in order to draw us to himself. God alone can satisfy this desire." } },
    { "type": "qa", "n": 362, "id": "soru-362", "ccc": "1720–1724, 1727–1729",
      "tr": { "q": "Sonsuz mutluluk nedir?",
              "a": "Sonsuz mutluluk, sonsuz yaşamda Tanrı'yı görmektir; bu yaşamda tam anlamıyla “tanrısal doğaya” (2 Petrus 1:4), Mesih'in yüceliğine ve Üçlü Birlik yaşamının sevincine ortak oluruz. Bu mutluluk insan yeteneklerini aşar. Ona götüren lütuf gibi o da Tanrı'nın doğaüstü ve karşılıksız bir armağanıdır. Vaat edilen bu mutluluk bizi dünyasal nimetlerle ilgili belirleyici ahlaki seçimlerle yüz yüze getirir ve Tanrı'yı her şeyden çok sevmeye yöneltir." },
      "en": { "q": "What is eternal happiness?",
              "a": "It is the vision of God in eternal life in which we are fully “partakers of the divine nature” (2 Peter 1:4), of the glory of Christ and of the joy of the trinitarian life. This happiness surpasses human capabilities. It is a supernatural and gratuitous gift of God just as is the grace which leads to it. This promised happiness confronts us with decisive moral choices concerning earthly goods and urges us to love God above all things." } },
    { "type": "heading", "level": 4, "id": "insanin-ozgurlugu",
      "tr": "İnsanın Özgürlüğü",
      "en": "Man's Freedom" },
    { "type": "qa", "n": 363, "id": "soru-363", "ccc": "1730–1733, 1743–1744",
      "tr": { "q": "Özgürlük nedir?",
              "a": "Özgürlük, Tanrı'nın verdiği, hareket etme ya da etmeme, şunu ya da bunu yapma ve böylece kendi sorumluluğuyla bilinçli eylemlerde bulunma gücüdür. Özgürlük, tam anlamıyla insani eylemleri belirginleştirir. Kişi iyi olanı ne kadar çok yaparsa o kadar özgür olur. Özgürlük, en yüce iyi ve mutluluğumuz olan Tanrı'ya yöneldiğinde kendine özgü yetkinliğine ulaşır. Özgürlük aynı zamanda iyi ile kötü arasında seçim yapma olasılığını da içerir. Kötüyü seçmek özgürlüğün kötüye kullanılmasıdır ve günahın köleliğine götürür." },
      "en": { "q": "What is freedom?",
              "a": "Freedom is the power given by God to act or not to act, to do this or to do that, and so to perform deliberate actions on one's own responsibility. Freedom characterizes properly human acts. The more one does what is good, the freer one becomes. Freedom attains its proper perfection when it is directed toward God, the highest good and our beatitude. Freedom implies also the possibility of choosing between good and evil. The choice of evil is an abuse of freedom and leads to the slavery of sin." } },
    { "type": "qa", "n": 364, "id": "soru-364", "ccc": "1734–1737, 1745–1746",
      "tr": { "q": "Özgürlük ile sorumluluk arasındaki ilişki nedir?",
              "a": "Özgürlük insanları, eylemleri gönüllü olduğu ölçüde bu eylemlerden sorumlu kılar; ancak bir eylemin yüklenebilirliği ve sorumluluğu bilgisizlik, dikkatsizlik, zorlama, korku, düzensiz bağlılıklar ya da alışkanlık nedeniyle azalabilir, hatta bazen ortadan kalkabilir." },
      "en": { "q": "What is the relationship between freedom and responsibility?",
              "a": "Freedom makes people responsible for their actions to the extent that they are voluntary, even if the imputability and responsibility for an action can be diminished or sometimes cancelled by ignorance, inadvertence, duress, fear, inordinate attachments, or habit." } },
    { "type": "qa", "n": 365, "id": "soru-365", "ccc": "1738, 1747",
      "tr": { "q": "Neden herkesin özgürlüğünü kullanma hakkı vardır?",
              "a": "Özgürlüğü kullanma hakkı herkese aittir; çünkü bu hak, kişinin insan onurundan ayrılamaz. Bu nedenle bu hakka, özellikle ahlaki ve dinsel konularda her zaman saygı gösterilmeli ve bu hak ortak iyiliğin ve adil bir kamu düzeninin sınırları içinde sivil otorite tarafından tanınmalı ve korunmalıdır." },
      "en": { "q": "Why does everyone have a right to exercise freedom?",
              "a": "The right to the exercise of freedom belongs to everyone because it is inseparable from his or her dignity as a human person. Therefore this right must always be respected, especially in moral and religious matters, and it must be recognized and protected by civil authority within the limits of the common good and a just public order." } },
    { "type": "qa", "n": 366, "id": "soru-366", "ccc": "1739–1742, 1748",
      "tr": { "q": "İnsan özgürlüğünün kurtuluş tasarısında yeri nedir?",
              "a": "Özgürlüğümüz ilk günah yüzünden zayıflamıştır. Bu zayıflık, ardı ardına işlenen günahlarla şiddetlenir. Ancak Mesih bizi “özgür olalım diye” (Galatyalılar 5:1) özgür kıldı. Kutsal Ruh lütfuyla bizi, Kilise'de ve dünyada O'nun özgür iş arkadaşları olmamız için ruhsal özgürlüğe götürür." },
      "en": { "q": "What place does human freedom have in the plan of salvation?",
              "a": "Our freedom is weakened because of original sin. This weakness is intensified because of successive sins. Christ, however, set us free “so that we should remain free” (<em>Galatians</em> 5:1). With his grace, the Holy Spirit leads us to spiritual freedom to make us free co-workers with him in the Church and in the world." } },
    { "type": "qa", "n": 367, "id": "soru-367", "ccc": "1749–1754, 1757–1758",
      "tr": { "q": "İnsan eylemlerinin ahlakiliğinin kaynakları nelerdir?",
              "a": "İnsan eylemlerinin ahlakiliği üç kaynağa bağlıdır: gerçek ya da görünüşte bir iyi olan <em>seçilen nesneye</em>; eylemde bulunan öznenin <em>niyetine</em>, yani öznenin eylemi hangi amaçla yaptığına; ve eylemin sonuçlarını da içeren <em>koşullarına</em>." },
      "en": { "q": "What are the sources of the morality of human acts?",
              "a": "The morality of human acts depends on three sources: <em>the object chosen</em>, either a true or apparent good; <em>the intention</em> of the subject who acts, that is, the purpose for which the subject performs the act; and <em>the circumstances</em> of the act, which include its consequences." } },
    { "type": "qa", "n": 368, "id": "soru-368", "ccc": "1755–1756, 1759–1760",
      "tr": { "q": "Bir eylem ne zaman ahlaken iyidir?",
              "a": "Bir eylem, nesnenin, amacın ve koşulların iyiliğini aynı anda taşıdığında ahlaken iyidir. Seçilen bir nesne, niyet iyi olsa bile, tek başına eylemin bütününü bozabilir. Ondan iyilik doğsun diye kötülük yapmak meşru değildir. Kötü bir amaç, nesne kendi içinde iyi olsa bile eylemi bozar. Öte yandan, iyi bir amaç, eylemin nesnesi kötüyse o eylemi iyi yapmaz; çünkü amaç araçları haklı çıkarmaz. Koşullar, eylemde bulunan kişinin sorumluluğunu artırabilir ya da azaltabilir, ama eylemlerin kendi ahlaki niteliğini değiştiremez. Kendi içinde kötü olan bir eylemi asla iyi yapmazlar." },
      "en": { "q": "When is an act morally good?",
              "a": "An act is morally good when it assumes simultaneously the goodness of the object, of the end, and of the circumstances. A chosen object can by itself vitiate an act in its entirety, even if the intention is good. It is not licit to do evil so that good may result from it. An evil end corrupts the action, even if the object is good in itself. On the other hand, a good end does not make an act good if the object of that act is evil, since the end does not justify the means. Circumstances can increase or diminish the responsibility of the one who is acting but they cannot change the moral quality of the acts themselves. They never make good an act which is in itself evil." } },
    { "type": "qa", "n": 369, "id": "soru-369", "ccc": "1756, 1761",
      "tr": { "q": "Her zaman meşru olmayan eylemler var mıdır?",
              "a": "Kendi içlerinde ve kendileri bakımından, nesneleri nedeniyle her zaman meşru olmayan bazı eylemler vardır (örneğin küfür, adam öldürme, zina). Bu tür eylemleri seçmek, iradenin bir düzensizliğini, yani bunlardan doğabilecek iyi sonuçlara başvurularak asla haklı çıkarılamayacak bir ahlaki kötülüğü içerir." },
      "en": { "q": "Are there acts which are always illicit?",
              "a": "There are some acts which, in and of themselves, are always illicit by reason of their object (for example, blasphemy, homicide, adultery). Choosing such acts entails a disorder of the will, that is, a moral evil which can never be justified by appealing to the good effects which could possibly result from them." } },
    { "type": "heading", "level": 4, "id": "tutkularin-ahlaki",
      "tr": "Tutkuların Ahlakı",
      "en": "The Morality of the Passions" },
    { "type": "qa", "n": 370, "id": "soru-370", "ccc": "1762–1766, 1771–1772",
      "tr": { "q": "Tutkular nedir?",
              "a": "Tutkular, insan ruhbiliminin doğal bileşenleri olan duyusal isteğin duyguları, heyecanları ya da hareketleridir; kişiyi iyi ya da kötü olarak algılananın ışığında hareket etmeye ya da etmemeye yöneltirler. Başlıca tutkular sevgi ve nefret, arzu ve korku, sevinç, üzüntü ve öfkedir. Temel tutku, iyinin çekiciliğine kapılan sevgidir. Kişi ancak gerçek ya da görünüşte iyi olanı sevebilir." },
      "en": { "q": "What are the passions?",
              "a": "The passions are the feelings, the emotions or the movements of the sensible appetite - natural components of human psychology - which incline a person to act or not to act in view of what is perceived as good or evil. The principal passions are love and hatred, desire and fear, joy, sadness, and anger. The chief passion is love which is drawn by the attraction of the good. One can only love what is good, real or apparent." } },
    { "type": "qa", "n": 371, "id": "soru-371", "ccc": "1767–1770, 1773–1775",
      "tr": { "q": "Tutkular ahlaken iyi mi kötü müdür?",
              "a": "Tutkular, duyusal isteğin hareketleri oldukları ölçüde, kendi içlerinde ne iyi ne de kötüdür. İyi bir eyleme katkıda bulunduklarında iyidirler, aksi durumda kötüdürler. Erdemler tarafından üstlenilebilir ya da kötü alışkanlıklar tarafından saptırılabilirler." },
      "en": { "q": "Are the passions morally good or bad?",
              "a": "The passions insofar as they are movements of the sensible appetite are neither good nor bad in themselves. They are good when they contribute to a good action and they are evil in the opposite case. They can be taken up into the virtues or perverted by the vices." } },
    { "type": "heading", "level": 4, "id": "ahlaki-vicdan",
      "tr": "Ahlaki Vicdan",
      "en": "The Moral Conscience" },
    { "type": "qa", "n": 372, "id": "soru-372", "ccc": "1776–1780, 1795–1797",
      "tr": { "q": "Ahlaki vicdan nedir?",
              "a": "Kişinin yüreğinde bulunan ahlaki vicdan, uygun anda ona iyiyi yapmasını ve kötüden kaçınmasını buyuran bir akıl yargısıdır. Ahlaki vicdan sayesinde insan kişisi, yapılacak ya da yapılmış bir eylemin ahlaki niteliğini algılar ve eylemin sorumluluğunu üstlenebilir. Sağduyulu kişi, ahlaki vicdanına kulak verdiğinde, kendisine konuşan Tanrı'nın sesini işitebilir." },
      "en": { "q": "What is the moral conscience?",
              "a": "Moral conscience, present in the heart of the person, is a judgment of reason which at the appropriate moment enjoins him to do good and to avoid evil. Thanks to moral conscience, the human person perceives the moral quality of an act to be done or which has already been done, permitting him to assume responsibility for the act. When attentive to moral conscience, the prudent person can hear the voice of God who speaks to him or her." } },
    { "type": "qa", "n": 373, "id": "soru-373", "ccc": "1780–1782, 1798",
      "tr": { "q": "İnsan kişisinin onuru ahlaki vicdan için ne gerektirir?",
              "a": "İnsan kişisinin onuru ahlaki vicdanın doğruluğunu (yani akla ve Tanrı'nın yasasına göre adil ve iyi olanla uyumlu olmasını) gerektirir. Bu kişisel onur nedeniyle hiç kimse vicdanına aykırı davranmaya zorlanamaz; ortak iyiliğin sınırları içinde, özellikle dinsel konularda, vicdanına göre davranması da engellenemez." },
      "en": { "q": "What does the dignity of the human person imply for the moral conscience?",
              "a": "The dignity of a human person requires the uprightness of a moral conscience (which is to say that it be in accord with what is just and good according to reason and the law of God). Because of this personal dignity, no one may be forced to act contrary to conscience; nor, within the limits of the common good, be prevented from acting according to it, especially in religious matters." } },
    { "type": "qa", "n": 374, "id": "soru-374", "ccc": "1783–1788, 1799–1800",
      "tr": { "q": "Ahlaki vicdan doğru ve gerçeğe uygun olacak biçimde nasıl oluşturulur?",
              "a": "Doğru ve gerçeğe uygun bir ahlaki vicdan, eğitimle ve Tanrı Sözü'nün ve Kilise'nin öğretisinin özümsenmesiyle oluşur. Kutsal Ruh'un armağanlarıyla desteklenir ve bilge kişilerin öğütleriyle yardım görür. Dua ve vicdan muhasebesi de kişinin ahlaki gelişimine büyük ölçüde yardımcı olabilir." },
      "en": { "q": "How is a moral conscience formed to be upright and truthful?",
              "a": "An upright and true moral conscience is formed by education and by assimilating the Word of God and the teaching of the Church. It is supported by the gifts of the Holy Spirit and helped by the advice of wise people. Prayer and an examination of conscience can also greatly assist one’s moral formation." } },
    { "type": "qa", "n": 375, "id": "soru-375", "ccc": "1789",
      "tr": { "q": "Vicdanın her zaman izlemesi gereken kurallar nelerdir?",
              "a": "Üç genel kural vardır: 1) ondan iyilik doğsun diye asla kötülük yapılamaz; 2) <em>Altın Kural</em> denen kural: “İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın” (Matta 7:12); 3) sevgi her zaman komşuya ve onun vicdanına saygı yoluyla ilerler; ama bu, nesnel olarak kötü olan bir şeyi iyi olarak kabul etmek anlamına gelmez." },
      "en": { "q": "What norms must conscience always follow?",
              "a": "There are three general norms: 1) one may never do evil so that good may result from it; 2) the so-called <em>Golden Rule</em>, “Whatever you wish that men would do to you, do so to them” (<em>Matthew</em> 7:12); 3) charity always proceeds by way of respect for one’s neighbor and his conscience, even though this does not mean accepting as good something that is objectively evil." } },
    { "type": "qa", "n": 376, "id": "soru-376", "ccc": "1790–1794, 1801–1802",
      "tr": { "q": "Ahlaki vicdan yanlış yargılarda bulunabilir mi?",
              "a": "Kişi her zaman kendi vicdanının kesin yargısına uymalıdır; ama her zaman kendisini kişisel suçtan muaf tutmayabilecek nedenlerle yanlış yargılarda bulunabilir. Bununla birlikte, istem dışı bilgisizlik yüzünden işlenen kötü bir eylem, nesnel olarak kötü kalsa bile kişiye yüklenemez. Bu nedenle kişi ahlaki vicdanının yanlışlarını düzeltmek için çalışmalıdır." },
      "en": { "q": "Can a moral conscience make erroneous judgments?",
              "a": "A person must always obey the certain judgment of his own conscience but he could make erroneous judgments for reasons that may not always exempt him from personal guilt. However, an evil act committed through involuntary ignorance is not imputable to the person, even though the act remains objectively evil. One must therefore work to correct the errors of moral conscience." } },
    { "type": "heading", "level": 4, "id": "erdemler",
      "tr": "Erdemler",
      "en": "The Virtues" },
    { "type": "qa", "n": 377, "id": "soru-377", "ccc": "1803, 1833",
      "tr": { "q": "Erdem nedir?",
              "a": "Erdem, iyiyi yapmaya yönelik alışkanlık haline gelmiş ve sağlam bir eğilimdir. “Erdemli bir yaşamın amacı Tanrı'ya benzemektir” ([[Nyssalı Aziz Gregorios|Saint Gregory of Nyssa]]). İnsani erdemler ve tanrısal erdemler vardır." },
      "en": { "q": "What is a virtue?",
              "a": "A virtue is an habitual and firm disposition to do the good. “The goal of a virtuous life is to become like God” (Saint Gregory of Nyssa). There are human virtues and theological virtues." } },
    { "type": "qa", "n": 378, "id": "soru-378", "ccc": "1804, 1810–1811, 1834, 1839",
      "tr": { "q": "İnsani erdemler nelerdir?",
              "a": "İnsani erdemler, eylemlerimizi yöneten, tutkularımızı düzenleyen ve davranışlarımızı akla ve imana göre yönlendiren, aklın ve iradenin alışkanlık haline gelmiş ve kalıcı yetkinlikleridir. Ahlaken iyi eylemlerin tekrarlanmasıyla edinilir ve güçlenirler; tanrısal lütufla arınır ve yücelirler." },
      "en": { "q": "What are the human virtues?",
              "a": "The human virtues are habitual and stable perfections of the intellect and will that govern our actions, order our passions and guide our conduct according to reason and faith. They are acquired and strengthened by the repetition of morally good acts and they are purified and elevated by divine grace." } },
    { "type": "qa", "n": 379, "id": "soru-379", "ccc": "1805, 1834",
      "tr": { "q": "Başlıca insani erdemler hangileridir?",
              "a": "Başlıca insani erdemlere, diğer bütün erdemlerin çevresinde toplandığı ve erdemli bir yaşamın menteşeleri olan <em>ana</em> (kardinal) erdemler denir. Ana erdemler şunlardır: sağduyu, adalet, metanet (yüreklilik) ve ölçülülük." },
      "en": { "q": "What are the principal human virtues?",
              "a": "The principal human virtues are called the <em>cardinal</em> virtues, under which all the other virtues are grouped and which are the hinges of a virtuous life. The cardinal virtues are: prudence, justice, fortitude, and temperance." } },
    { "type": "qa", "n": 380, "id": "soru-380", "ccc": "1806, 1835",
      "tr": { "q": "Sağduyu nedir?",
              "a": "Sağduyu, aklı her durumda gerçek iyimizi ayırt etmeye ve ona ulaşmak için doğru araçları seçmeye hazırlar. Sağduyu, diğer erdemlere kurallarını ve ölçülerini göstererek onlara yön verir." },
      "en": { "q": "What is prudence?",
              "a": "Prudence disposes reason to discern in every circumstance our true good and to choose the right means for achieving it. Prudence guides the other virtues by pointing out their rule and measure." } },
    { "type": "qa", "n": 381, "id": "soru-381", "ccc": "1807, 1836",
      "tr": { "q": "Adalet nedir?",
              "a": "Adalet, başkalarına hakları olanı vermeye yönelik sağlam ve sürekli bir iradeden oluşur. Tanrı'ya karşı adalete “din erdemi” denir." },
      "en": { "q": "What is justice?",
              "a": "Justice consists in the firm and constant will to give to others their due. Justice toward God is called “the virtue of religion.”" } },
    { "type": "qa", "n": 382, "id": "soru-382", "ccc": "1808, 1837",
      "tr": { "q": "Metanet (yüreklilik) nedir?",
              "a": "Metanet, güçlükler karşısında kararlılığı ve iyiliğin peşinde sebatı güvence altına alır. Haklı bir dava uğruna gerekirse kendi yaşamını feda edebilme yeteneğine dek uzanır." },
      "en": { "q": "What is fortitude?",
              "a": "Fortitude assures firmness in difficulties and constancy in the pursuit of the good. It reaches even to the ability of possibly sacrificing one’s own life for a just cause." } },
    { "type": "qa", "n": 383, "id": "soru-383", "ccc": "1809, 1838",
      "tr": { "q": "Ölçülülük nedir?",
              "a": "Ölçülülük, hazların çekiciliğini dengeler, iradenin içgüdüler üzerinde egemenliğini güvence altına alır ve yaratılmış nimetlerin kullanımında denge sağlar." },
      "en": { "q": "What is temperance?",
              "a": "Temperance moderates the attraction of pleasures, assures the mastery of the will over instincts and provides balance in the use of created goods." } },
    { "type": "qa", "n": 384, "id": "soru-384", "ccc": "1812–1813, 1840–1841",
      "tr": { "q": "Tanrısal erdemler nelerdir?",
              "a": "Tanrısal erdemlerin kökeni, gerekçesi ve dolaysız nesnesi Tanrı'nın Kendisidir. Kutsallaştırıcı lütufla birlikte içimize konan bu erdemler, kişiye Üçlü Birlik'le bir ilişki içinde yaşama yeteneği verir. Hristiyanın ahlaki etkinliğinin temeli ve canlandırıcı gücüdürler ve insani erdemlere yaşam verirler. İnsan varlığının yetilerinde Kutsal Ruh'un varlığının ve eyleminin güvencesidirler." },
      "en": { "q": "What are the theological virtues?",
              "a": "The theological virtues have God himself as their origin, motive and direct object. Infused with sanctifying grace, they bestow on one the capacity to live in a relationship with the Trinity. They are the foundation and the energizing force of the Christian’s moral activity and they give life to the human virtues. They are the pledge of the presence and action of the Holy Spirit in the faculties of the human being." } },
    { "type": "qa", "n": 385, "id": "soru-385", "ccc": "1813",
      "tr": { "q": "Tanrısal erdemler hangileridir?",
              "a": "Tanrısal erdemler iman, umut ve sevgidir." },
      "en": { "q": "What are the theological virtues?",
              "a": "The theological virtues are faith, hope, and charity." } },
    { "type": "qa", "n": 386, "id": "soru-386", "ccc": "1814–1816, 1842",
      "tr": { "q": "İman erdemi nedir?",
              "a": "İman, Tanrı'ya ve O'nun bize açıkladığı ve Kilise'nin inanmamız için bize sunduğu her şeye inandığımız tanrısal erdemdir; çünkü Tanrı Gerçeğin Kendisidir. İmanla insan kişisi kendini özgürce Tanrı'ya adar. Bu nedenle inanlı Tanrı'nın isteğini bilmeye ve yerine getirmeye çalışır; çünkü “iman sevgi aracılığıyla etkin olur” (Galatyalılar 5:6)." },
      "en": { "q": "What is the virtue of faith?",
              "a": "Faith is the theological virtue by which we believe in God and all that he has revealed to us and that the Church proposes for our belief because God is Truth itself. By faith the human person freely commits himself to God. Therefore, the believer seeks to know and do the will of God because “faith works through charity” (<em>Galatians</em> 5:6)." } },
    { "type": "qa", "n": 387, "id": "soru-387", "ccc": "1817–1821, 1843",
      "tr": { "q": "Umut nedir?",
              "a": "Umut, sonsuz yaşamı mutluluğumuz olarak Tanrı'dan dilediğimiz ve beklediğimiz tanrısal erdemdir; Mesih'in vaatlerine güvenir ve onu hak etmek ve yeryüzündeki yaşamımızın sonuna dek sebat etmek için Kutsal Ruh'un lütfunun yardımına dayanırız." },
      "en": { "q": "What is hope?",
              "a": "Hope is the theological virtue by which we desire and await from God eternal life as our happiness, placing our trust in Christ's promises and relying on the help of the grace of the Holy Spirit to merit it and to persevere to the end of our earthly life." } },
    { "type": "qa", "n": 388, "id": "soru-388", "ccc": "1822–1829, 1844",
      "tr": { "q": "Sevgi nedir?",
              "a": "Sevgi, Tanrı'yı her şeyden çok, komşumuzu da Tanrı sevgisi uğruna kendimiz gibi sevdiğimiz tanrısal erdemdir. İsa sevgiyi yeni buyruk, Yasa'nın doluluğu yapar. Sevgi “yetkinliğin bağıdır” (Koloseliler 3:14) ve kendilerine yaşam, esin ve düzen verdiği diğer erdemlerin temelidir. Sevgi olmadan “bir hiçim” ve “hiçbir kazancım olmaz” (1 Korintliler 13:1-3)." },
      "en": { "q": "What is charity?",
              "a": "Charity is the theological virtue by which we love God above all things and our neighbor as ourselves for the love of God. Jesus makes charity the new commandment, the fullness of the law. “It is the bond of perfection” (<em>Colossians</em> 3:14) and the foundation of the other virtues to which it gives life, inspiration, and order. Without charity “I am nothing” and “I gain nothing” (<em>1 Corinthians</em> 13:1-3)." } },
    { "type": "qa", "n": 389, "id": "soru-389", "ccc": "1830–1831, 1845",
      "tr": { "q": "Kutsal Ruh'un armağanları nelerdir?",
              "a": "Kutsal Ruh'un armağanları, bizi tanrısal esinleri izlemeye yatkın kılan kalıcı eğilimlerdir. Yedi tanedir: bilgelik, anlayış, öğüt, metanet (yüreklilik), bilgi, dindarlık ve Rab korkusu." },
      "en": { "q": "What are the gifts of the Holy Spirit?",
              "a": "The gifts of the Holy Spirit are permanent dispositions which make us docile in following divine inspirations. They are seven: wisdom, understanding, counsel, fortitude, knowledge, piety, and fear of the Lord." } },
    { "type": "qa", "n": 390, "id": "soru-390", "ccc": "1832",
      "tr": { "q": "Kutsal Ruh'un meyveleri nelerdir?",
              "a": "Kutsal Ruh'un <em>meyveleri</em>, sonsuz yüceliğin ilk ürünleri olarak içimizde oluşan yetkinliklerdir. Kilise Geleneği bunlardan on ikisini sayar: sevgi, sevinç, esenlik, sabır, nezaket, iyilik, cömertlik, yumuşak huyluluk, sadakat, alçakgönüllülük (ölçülülük), kendini denetleme ve iffet (Galatyalılar 5:22-23, Vulgata)." },
      "en": { "q": "What are the fruits of the Holy Spirit?",
              "a": "The <em>fruits</em> of the Holy Spirit are perfections formed in us as the first fruits of eternal glory. The tradition of the Church lists twelve of them: charity, joy, peace, patience, kindness, goodness, generosity, gentleness, faithfulness, modesty, self-control, and chastity (<em>Galatians</em> 5:22-23, Vulgate)." } },
    { "type": "heading", "level": 4, "id": "gunah",
      "tr": "Günah",
      "en": "Sin" },
    { "type": "qa", "n": 391, "id": "soru-391", "ccc": "1846–1848, 1870",
      "tr": { "q": "Tanrı'nın merhametini kabul etmek bizden ne gerektirir?",
              "a": "Hatalarımızı kabul etmemizi ve günahlarımızdan tövbe etmemizi gerektirir. Tanrı'nın Kendisi Sözü ve Ruhu aracılığıyla günahlarımızı açığa çıkarır ve bize vicdanın gerçeğini ve bağışlanma umudunu verir." },
      "en": { "q": "What does the acceptance of God’s mercy require from us?",
              "a": "It requires that we admit our faults and repent of our sins. God himself by his Word and his Spirit lays bare our sins and gives us the truth of conscience and the hope of forgiveness." } },
    { "type": "qa", "n": 392, "id": "soru-392", "ccc": "1849–1851, 1871–1872",
      "tr": { "q": "Günah nedir?",
              "a": "Günah, “sonsuz Yasa'ya aykırı bir söz, bir eylem ya da bir arzudur” ([[Aziz Augustinus|Saint Augustine]]). O'nun sevgisine itaatsizlik içinde Tanrı'ya karşı işlenmiş bir suçtur. İnsan doğasını yaralar ve insan dayanışmasına zarar verir. Mesih çilesinde günahın ağırlığını tümüyle açığa çıkardı ve onu merhametiyle yendi." },
      "en": { "q": "What is sin?",
              "a": "Sin is “a word, an act, or a desire contrary to the eternal Law” (Saint Augustine). It is an offense against God in disobedience to his love. It wounds human nature and injures human solidarity. Christ in his passion fully revealed the seriousness of sin and overcame it with his mercy." } },
    { "type": "qa", "n": 393, "id": "soru-393", "ccc": "1852–1853, 1873",
      "tr": { "q": "Günahın çeşitleri var mıdır?",
              "a": "Çok sayıda günah çeşidi vardır. Nesnelerine ya da çiğnedikleri erdemlere veya buyruklara göre ayırt edilebilirler. Doğrudan Tanrı'yı, komşuyu ya da kendimizi ilgilendirebilirler. Ayrıca düşünce, söz, eylem ya da ihmal günahları olarak da ayrılabilirler." },
      "en": { "q": "Is there a variety of sins?",
              "a": "There are a great many kinds of sins. They can be distinguished according to their object or according to the virtues or commandments which they violate. They can directly concern God, neighbor, or ourselves. They can also be divided into sins of thought, of word, of deed, or of omission." } },
    { "type": "qa", "n": 394, "id": "soru-394", "ccc": "1854",
      "tr": { "q": "Günahlar ağırlıklarına göre nasıl ayırt edilir?",
              "a": "Ölümcül günah ile hafif günah arasında ayrım yapılır." },
      "en": { "q": "How are sins distinguished according to their gravity?",
              "a": "A distinction is made between mortal and venial sin." } },
    { "type": "qa", "n": 395, "id": "soru-395", "ccc": "1855–1861, 1874",
      "tr": { "q": "Kişi ne zaman ölümcül günah işler?",
              "a": "Ağır bir konu, tam bilgi ve bilinçli rıza aynı anda bulunduğunda kişi ölümcül günah işler. Bu günah içimizdeki sevgiyi yok eder, bizi kutsallaştırıcı lütuftan yoksun bırakır ve tövbe edilmezse bizi cehennemin sonsuz ölümüne götürür. Olağan yolla Vaftiz ve Tövbe ya da Barışma sırları aracılığıyla bağışlanabilir." },
      "en": { "q": "When does one commit a mortal sin?",
              "a": "One commits a mortal sin when there are simultaneously present: grave matter, full knowledge, and deliberate consent. This sin destroys charity in us, deprives us of sanctifying grace, and, if unrepented, leads us to the eternal death of hell. It can be forgiven in the ordinary way by means of the sacraments of Baptism and of Penance or Reconciliation." } },
    { "type": "qa", "n": 396, "id": "soru-396", "ccc": "1862–1864, 1875",
      "tr": { "q": "Kişi ne zaman hafif günah işler?",
              "a": "Ölümcül günahtan özünde farklı olan hafif günahı kişi, söz konusu konu daha az ağır olduğunda ya da ağır olsa bile tam bilgi veya tam rıza bulunmadığında işler. Hafif günah Tanrı'yla antlaşmayı bozmaz, ama sevgiyi zayıflatır ve yaratılmış nimetlere karşı düzensiz bir bağlılığı gösterir. Canın erdemleri uygulamada ve ahlaki iyiyi yerine getirmede ilerlemesini engeller. Arındırıcı olan geçici cezayı hak eder." },
      "en": { "q": "When does one commit a venial sin?",
              "a": "One commits a venial sin, which is essentially different from a mortal sin, when the matter involved is less serious or, even if it is grave, when full knowledge or complete consent are absent. Venial sin does not break the covenant with God but it weakens charity and manifests a disordered affection for created goods. It impedes the progress of a soul in the exercise of the virtues and in the practice of moral good. It merits temporal punishment which purifies." } },
    { "type": "qa", "n": 397, "id": "soru-397", "ccc": "1865, 1876",
      "tr": { "q": "Günah nasıl çoğalır?",
              "a": "Günah, günaha bir eğilim yaratır; aynı eylemlerin tekrarlanmasıyla kötü alışkanlığı doğurur." },
      "en": { "q": "How does sin proliferate?",
              "a": "Sin creates a proclivity to sin; it engenders vice by repetition of the same acts." } },
    { "type": "qa", "n": 398, "id": "soru-398", "ccc": "1866–1867",
      "tr": { "q": "Kötü alışkanlıklar (ahlaki kusurlar) nedir?",
              "a": "Kötü alışkanlıklar erdemlerin karşıtıdır. Vicdanı karartan ve kişiyi kötülüğe yönelten sapkın alışkanlıklardır. Kötü alışkanlıklar, <em>ana</em> günahlar denen yedi günaha bağlanabilir: gurur, açgözlülük, kıskançlık, öfke, şehvet, oburluk ve tembellik (acedia)." },
      "en": { "q": "What are vices?",
              "a": "Vices are the opposite of virtues. They are perverse habits which darken the conscience and incline one to evil. The vices can be linked to the seven, so-called, <em>capital</em> sins which are: pride, avarice, envy, anger, lust, gluttony, and sloth or acedia." } },
    { "type": "qa", "n": 399, "id": "soru-399", "ccc": "1868",
      "tr": { "q": "Başkalarının işlediği günahlarda bizim bir sorumluluğumuz var mıdır?",
              "a": "Onlarla suç ortaklığı içinde işbirliği yaptığımızda böyle bir sorumluluğumuz vardır." },
      "en": { "q": "Do we have any responsibility for sins committed by others?",
              "a": "We do have such a responsibility when we culpably cooperate with them." } },
    { "type": "qa", "n": 400, "id": "soru-400", "ccc": "1869",
      "tr": { "q": "Günah <em>yapıları</em> nedir?",
              "a": "Günah <em>yapıları</em>, tanrısal yasaya aykırı olan toplumsal durumlar ya da kurumlardır. Kişisel günahların ifadesi ve sonucudurlar." },
      "en": { "q": "What are <em>structures</em> of sin?",
              "a": "<em>Structures</em> of sin are social situations or institutions that are contrary to the divine law. They are the expression and effect of personal sins." } },
    { "type": "heading", "level": 3, "id": "ikinci-baslik-insan-toplulugu",
      "tr": "İkinci Başlık: İnsan Topluluğu",
      "en": "Chapter Two: The Human Community" },
    { "type": "heading", "level": 4, "id": "kisi-ve-toplum",
      "tr": "Kişi ve Toplum",
      "en": "The Person and Society" },
    { "type": "qa", "n": 401, "id": "soru-401", "ccc": "1877–1880, 1890–1891",
      "tr": { "q": "İnsanın toplumsal boyutu neden oluşur?",
              "a": "Mutluluğa kişisel çağrıyla birlikte insan kişisinin, doğasının ve çağrısının temel bir bileşeni olarak toplumsal bir boyutu da vardır. Gerçekten de herkes aynı amaca, Tanrı'nın Kendisine çağrılmıştır. Tanrısal Kişilerin birliği ile insanların gerçek ve sevgi içinde aralarında kurmaları gereken kardeşlik arasında belli bir benzerlik vardır. Komşu sevgisi Tanrı sevgisinden ayrılamaz." },
      "en": { "q": "In what does the social dimension of man consist?",
              "a": "Together with the personal call to beatitude, the human person has a communal dimension as an essential component of his nature and vocation. Indeed, all are called to the same end, God himself. There is a certain resemblance between the communion of the divine Persons and the fraternity that people are to establish among themselves in truth and love. Love of neighbor is inseparable from love for God." } },
    { "type": "qa", "n": 402, "id": "soru-402", "ccc": "1881–1882, 1892–1893",
      "tr": { "q": "Kişi ile toplum arasındaki ilişki nedir?",
              "a": "İnsan <em>kişisi</em> bütün toplumsal kurumların ilkesi, öznesi ve amacıdır ve öyle olmalıdır. Aile ve sivil toplum gibi bazı topluluklar insan kişisi için gereklidir. <em>Yerellik (subsidiarite)</em> ilkesine gereken saygı gösterilerek ulusal ve uluslararası düzeydeki diğer birlikler de yararlıdır." },
      "en": { "q": "What is the relationship between the person and society?",
              "a": "The human <em>person</em> is and ought to be the principle, the subject and the end of all social institutions. Certain societies, such as the family and the civic community, are necessary for the human person. Also helpful are other associations on the national and international levels with due respect for the principle of <em>subsidiarity</em>." } },
    { "type": "qa", "n": 403, "id": "soru-403", "ccc": "1883–1885, 1894",
      "tr": { "q": "Yerellik (subsidiarite) ilkesi nedir?",
              "a": "Yerellik ilkesi, daha üst düzeydeki bir topluluğun daha alt düzeydeki bir topluluğa ait olan görevi üstlenmemesi ve onu yetkisinden yoksun bırakmaması gerektiğini söyler. Tersine, gerektiğinde onu desteklemelidir." },
      "en": { "q": "What is the principle of subsidiarity?",
              "a": "The principle of subsidiarity states that a community of a higher order should not assume the task belonging to a community of a lower order and deprive it of its authority. It should rather support it in case of need." } },
    { "type": "qa", "n": 404, "id": "soru-404", "ccc": "1886–1889, 1895–1896",
      "tr": { "q": "Sahih bir insan toplumu için başka ne gereklidir?",
              "a": "Sahih bir insan toplumu adalete saygıyı, değerlerin adil bir sıralamasını ve maddi ve içgüdüsel boyutların iç ve ruhsal boyutlara bağlı olmasını gerektirir. Özellikle günahın toplumsal ortamı bozduğu yerlerde, her kişiye ve bütün kişiye gerçekten hizmet edebilecek toplumsal değişiklikler elde etmek için yüreklerin dönüşümüne ve Tanrı'nın lütfuna çağrıda bulunmak gerekir. Adaletin uygulanmasını gerektiren ve mümkün kılan sevgi, en büyük toplumsal buyruktur." },
      "en": { "q": "What else is required for an authentic human society?",
              "a": "Authentic human society requires respect for justice, a just hierarchy of values, and the subordination of material and instinctual dimensions to interior and spiritual ones. In particular, where sin has perverted the social climate, it is necessary to call for the conversion of hearts and for the grace of God to obtain social changes that may really serve each person and the whole person. Charity, which requires and makes possible the practice of justice, is the greatest social commandment." } },
    { "type": "heading", "level": 4, "id": "toplumsal-yasama-katilim",
      "tr": "Toplumsal Yaşama Katılım",
      "en": "Participation in Social Life" },
    { "type": "qa", "n": 405, "id": "soru-405", "ccc": "1897–1902, 1918–1920",
      "tr": { "q": "Toplumdaki otoritenin temeli nedir?",
              "a": "Her insan topluluğu, düzeni koruyan ve ortak iyiliğin gerçekleşmesine katkıda bulunan meşru bir otoriteye ihtiyaç duyar. Böyle bir otoritenin temeli insan doğasındadır, çünkü Tanrı'nın kurduğu düzene karşılık gelir." },
      "en": { "q": "What is the foundation of the authority of society?",
              "a": "Every human community needs a legitimate authority that preserves order and contributes to the realization of the common good. The foundation of such authority lies in human nature because it corresponds to the order established by God." } },
    { "type": "qa", "n": 406, "id": "soru-406", "ccc": "1901–1904, 1921–1922",
      "tr": { "q": "Otorite ne zaman meşru biçimde kullanılır?",
              "a": "Otorite, ortak iyilik için hareket ettiğinde ve ona ulaşmak için ahlaken meşru araçlar kullandığında meşru biçimde kullanılır. Bu nedenle siyasal rejimler yurttaşlarının özgür kararıyla belirlenmelidir. Bazılarının keyfi iradesinin değil, yasanın egemen olduğu “hukukun üstünlüğü” ilkesine saygı göstermelidirler. Adil olmayan yasalar ve ahlak düzenine aykırı önlemler vicdanen bağlayıcı değildir." },
      "en": { "q": "When is authority exercised in a legitimate way?",
              "a": "Authority is exercised legitimately when it acts for the common good and employs morally licit means to attain it. Therefore, political regimes must be determined by the free decision of their citizens. They should respect the principle of the “rule of law” in which the law, and not the arbitrary will of some, is sovereign. Unjust laws and measures contrary to the moral order are not binding in conscience." } },
    { "type": "qa", "n": 407, "id": "soru-407", "ccc": "1905–1906, 1924",
      "tr": { "q": "Ortak iyilik nedir?",
              "a": "Ortak iyilik ile, insanların hem topluluklar hem de bireyler olarak kendi yetkinliklerine ulaşmalarını sağlayan toplumsal yaşam koşullarının bütünü kastedilir." },
      "en": { "q": "What is the common good?",
              "a": "By the common good is meant the sum total of those conditions of social life which allow people as groups and as individuals to reach their proper fulfillment." } },
    { "type": "qa", "n": 408, "id": "soru-408", "ccc": "1907–1909, 1925",
      "tr": { "q": "Ortak iyilik neleri içerir?",
              "a": "Ortak iyilik şunları içerir: kişinin temel haklarına saygı ve bu hakların geliştirilmesi, kişilerin ve toplumun ruhsal ve dünyasal nimetlerinin gelişmesi ve herkesin barışı ve güvenliği." },
      "en": { "q": "What is involved in the common good?",
              "a": "The common good involves: respect for and promotion of the fundamental rights of the person, the development of the spiritual and temporal goods of persons and society, and the peace and security of all." } },
    { "type": "qa", "n": 409, "id": "soru-409", "ccc": "1910–1912, 1927",
      "tr": { "q": "Ortak iyiliğin en eksiksiz gerçekleşmesi nerede bulunabilir?",
              "a": "Ortak iyiliğin en eksiksiz gerçekleşmesi, bütün insan ailesinin evrensel iyiliğini unutmadan yurttaşlarının ve ara toplulukların iyiliğini savunan ve geliştiren siyasal topluluklarda bulunur." },
      "en": { "q": "Where can one find the most complete realization of the common good?",
              "a": "The most complete realization of the common good is found in those political communities which defend and promote the good of their citizens and of intermediate groups without forgetting the universal good of the entire human family." } },
    { "type": "qa", "n": 410, "id": "soru-410", "ccc": "1913–1917, 1926",
      "tr": { "q": "Kişi ortak iyiliğin gerçekleşmesine nasıl katılır?",
              "a": "Bütün erkekler ve kadınlar, tuttukları yere ve üstlendikleri role göre, adil yasalara saygı göstererek ve kendi ailelerinin bakımı ve kendi işlerine bağlılık gibi kişisel sorumluluk taşıdıkları alanları üstlenerek ortak iyiliğin geliştirilmesine katılırlar. Yurttaşlar ayrıca olanaklar ölçüsünde kamusal yaşamda etkin bir rol almalıdır." },
      "en": { "q": "How does one participate in bringing about the common good?",
              "a": "All men and women according to the place and role that they occupy participate in promoting the common good by respecting just laws and taking charge of the areas for which they have personal responsibility such as the care of their own family and the commitment to their own work. Citizens also should take an active part in public life as far as possible." } },
    { "type": "heading", "level": 4, "id": "toplumsal-adalet",
      "tr": "Toplumsal Adalet",
      "en": "Social Justice" },
    { "type": "qa", "n": 411, "id": "soru-411", "ccc": "1928–1933, 1943–1944",
      "tr": { "q": "Toplum toplumsal adaleti nasıl güvence altına alır?",
              "a": "Toplum, kişinin onuruna ve haklarına toplumun kendi asıl amacı olarak saygı gösterdiğinde toplumsal adaleti güvence altına alır. Ayrıca toplum, ortak iyilikle ve otoritenin kullanılmasıyla bağlantılı olan toplumsal adaleti, derneklerin ve bireylerin kendilerine düşeni elde etmelerini sağlayan koşulları oluşturduğunda gerçekleştirir." },
      "en": { "q": "How does society ensure social justice?",
              "a": "Society ensures social justice when it respects the dignity and the rights of the person as the proper end of society itself. Furthermore, society pursues social justice, which is linked to the common good and to the exercise of authority, when it provides the conditions that allow associations and individuals to obtain what is their due." } },
    { "type": "qa", "n": 412, "id": "soru-412", "ccc": "1934–1935, 1945",
      "tr": { "q": "İnsan eşitliği neye dayanır?",
              "a": "Bütün kişiler, tek Tanrı'nın suretinde yaratılmış oldukları, aynı akıllı canla donatıldıkları, aynı doğaya ve kökene sahip oldukları ve tek ve biricik Kurtarıcı Mesih'te aynı tanrısal mutluluğa çağrıldıkları ölçüde eşit onura ve temel haklara sahiptir." },
      "en": { "q": "On what is human equality based?",
              "a": "All persons enjoy equal dignity and fundamental rights insofar as they are created in the image of the one God, are endowed with the same rational soul, have the same nature and origin, and are called in Christ, the one and only Savior, to the same divine beatitude." } },
    { "type": "qa", "n": 413, "id": "soru-413", "ccc": "1936–1938, 1946–1947",
      "tr": { "q": "Toplumsal eşitsizliklere nasıl bakmalıyız?",
              "a": "Milyonlarca insanı etkileyen, günaha dayalı toplumsal ve ekonomik eşitsizlikler vardır. Bu eşitsizlikler Müjde'yle açıkça çelişir ve adalete, kişilerin onuruna ve barışa aykırıdır. Bununla birlikte, insanlar arasında Tanrı'nın tasarısına giren çeşitli etkenlerin yol açtığı farklılıklar da vardır. Gerçekten de Tanrı, her birinin ihtiyaç duyduğunu başkalarından almasını ve özel yeteneklerle donatılmış olanların bunları başkalarıyla paylaşmasını ister. Bu tür farklılıklar insanları cömertliğe, iyiliğe ve nimetlerin paylaşılmasına teşvik eder ve çoğu zaman yükümlü kılar. Kültürlerin karşılıklı zenginleşmesini de teşvik ederler." },
      "en": { "q": "How are we to view social inequalities?",
              "a": "There are sinful social and economic inequalities which affect millions of human beings. These inequalities are in open contradiction to the Gospel and are contrary to justice, to the dignity of persons, and to peace. There are, however, differences among people caused by various factors which enter into the plan of God. Indeed, God wills that each might receive what he or she needs from others and that those endowed with particular talents should share them with others. Such differences encourage and often oblige people to the practice of generosity, kindness and the sharing of goods. They also foster the mutual enrichment of cultures." } },
    { "type": "qa", "n": 414, "id": "soru-414", "ccc": "1939–1942, 1948",
      "tr": { "q": "İnsan dayanışması nasıl ortaya konur?",
              "a": "İnsani ve Hristiyan kardeşlikten doğan dayanışma, ilk olarak nimetlerin adil dağılımıyla, emeğin hakkaniyetli karşılığıyla ve daha adil bir toplumsal düzen için gösterilen gayretle ortaya konur. Dayanışma <em>erdemi</em>, maddi nimetleri paylaşmaktan da önemli olan imanın ruhsal nimetlerinin paylaşılmasını da uygular." },
      "en": { "q": "How is human solidarity manifested?",
              "a": "Solidarity, which springs from human and Christian brotherhood, is manifested in the first place by the just distribution of goods, by a fair remuneration for work and by zeal for a more just social order. The <em>virtue</em> of solidarity also practices the sharing of the spiritual goods of faith which is even more important than sharing material goods." } },
    { "type": "heading", "level": 3, "id": "ucuncu-baslik-tanrinin-kurtulusu-yasa-ve-lutuf",
      "tr": "Üçüncü Başlık: Tanrı'nın Kurtuluşu – Yasa ve Lütuf",
      "en": "Chapter Three: God's Salvation: Law and Grace" },
    { "type": "heading", "level": 4, "id": "ahlak-yasasi",
      "tr": "Ahlak Yasası",
      "en": "The Moral Law" },
    { "type": "qa", "n": 415, "id": "soru-415", "ccc": "1950–1953, 1975–1978",
      "tr": { "q": "Ahlak yasası nedir?",
              "a": "Ahlak yasası, tanrısal Bilgeliğin bir eseridir. Vaat edilen mutluluğa götüren yolları ve davranış kurallarını belirler ve Tanrı'dan uzaklaştıran yolları yasaklar." },
      "en": { "q": "What is the moral law?",
              "a": "The moral law is a work of divine Wisdom. It prescribes the ways and the rules of conduct that lead to the promised beatitude and it forbids the ways that turn away from God." } },
    { "type": "qa", "n": 416, "id": "soru-416", "ccc": "1954–1960, 1978–1979",
      "tr": { "q": "Doğal ahlak yasası neden oluşur?",
              "a": "Yaratıcı tarafından her insanın yüreğine yazılmış olan doğal yasa, Tanrı'nın bilgeliğine ve iyiliğine bir katılımdan oluşur. Kişinin iyi ile kötüyü akılla ayırt etmesini sağlayan o kökendeki ahlak duyusunu ifade eder. Evrensel ve değişmezdir ve kişinin, insan topluluğunun ve medeni hukukun görevlerinin ve temel haklarının temelini belirler." },
      "en": { "q": "In what does the natural moral law consist?",
              "a": "The natural law which is inscribed by the Creator on the heart of every person consists in a participation in the wisdom and the goodness of God. It expresses that original moral sense which enables one to discern by reason the good and the bad. It is universal and immutable and determines the basis of the duties and fundamental rights of the person as well as those of the human community and civil law." } },
    { "type": "qa", "n": 417, "id": "soru-417", "ccc": "1960",
      "tr": { "q": "Böyle bir yasa herkes tarafından algılanır mı?",
              "a": "Günah yüzünden doğal yasa her zaman herkes tarafından aynı açıklık ve dolaysızlıkla algılanmaz ve tanınmaz." },
      "en": { "q": "Is such a law perceived by everyone?",
              "a": "Because of sin the natural law is not always perceived nor is it recognized by everyone with equal clarity and immediacy." } },
    { "type": "quote",
      "tr": "Bu nedenle Tanrı “insanların yüreklerinde okumadıklarını Yasa'nın levhalarına yazdı.” ([[Aziz Augustinus|Saint Augustine]])",
      "en": "For this reason God “wrote on the tables of the Law what men did not read in their hearts.” (Saint Augustine)" },
    { "type": "qa", "n": 418, "id": "soru-418", "ccc": "1961–1962, 1980",
      "tr": { "q": "Doğal yasa ile Eski Yasa arasındaki ilişki nedir?",
              "a": "Eski Yasa, açıklanmış Yasa'nın ilk aşamasıdır. Akla doğal olarak erişilebilir olan ve böylece kurtuluş antlaşmasında onaylanan ve doğrulanan birçok gerçeği ifade eder. On Emir'de özetlenen ahlaki buyrukları, insanın çağrısının temellerini atar, Tanrı ve komşu sevgisine aykırı olanı yasaklar ve bu sevgi için esas olanı buyurur." },
      "en": { "q": "What is the relationship between the natural law and the Old Law?",
              "a": "The Old Law is the first stage of revealed Law. It expresses many truths naturally accessible to reason and which are thus affirmed and authenticated in the covenant of salvation. Its moral prescriptions, which are summed up in the Ten Commandments of the Decalogue, lay the foundations of the human vocation, prohibit what is contrary to the love of God and neighbor, and prescribe what is essential to it." } },
    { "type": "qa", "n": 419, "id": "soru-419", "ccc": "1963–1964, 1982",
      "tr": { "q": "Eski Yasa'nın kurtuluş tasarısındaki yeri nedir?",
              "a": "Eski Yasa, akla erişilebilir birçok gerçeği bilmeyi sağladı, yapılması ya da yapılmaması gerekeni gösterdi ve her şeyden önce, bilge bir eğitmen gibi, kişiyi tövbeye ve Müjde'nin kabulüne hazırladı ve yatkın kıldı. Ancak kutsal, ruhsal ve iyi olmakla birlikte Eski Yasa hâlâ eksikti; çünkü kendi içinde, ona uyulması için Ruh'un gücünü ve lütfunu vermiyordu." },
      "en": { "q": "What place does the Old Law have in the plan of salvation?",
              "a": "The Old Law permitted one to know many truths which are accessible to reason, showed what must or must not be done and, above all, like a wise tutor, prepared and disposed one for conversion and for the acceptance of the Gospel. However, while being holy, spiritual, and good, the Old Law was still imperfect because in itself it did not give the strength and the grace of the Spirit for its observance." } },
    { "type": "qa", "n": 420, "id": "soru-420", "ccc": "1965–1972, 1983–1985",
      "tr": { "q": "Yeni Yasa ya da Müjde'nin Yasası nedir?",
              "a": "Mesih tarafından duyurulan ve yerine getirilen Yeni Yasa ya da Müjde'nin Yasası, doğal ve açıklanmış tanrısal yasanın doluluğu ve tamamlanmasıdır. Tanrı'yı ve komşuyu sevme ve Mesih'in bizi sevdiği gibi birbirimizi sevme buyruğunda özetlenir. Aynı zamanda içsel bir gerçekliktir: böyle bir sevgiyi mümkün kılan Kutsal Ruh'un lütfu. “Özgürlük yasasıdır” (Yakup 1:25), çünkü bizi sevginin itkisiyle kendiliğimizden hareket etmeye yöneltir." },
      "en": { "q": "What is the New Law or the Law of the Gospel?",
              "a": "The New Law or the Law of the Gospel, proclaimed and fulfilled by Christ, is the fullness and completion of the divine law, natural and revealed. It is summed up in the commandment to love God and neighbor and to love one another as Christ loved us. It is also an interior reality: the grace of the Holy Spirit which makes possible such love. It is “the law of freedom” (<em>Galatians</em> 1:25) because it inclines us to act spontaneously by the prompting of charity." },
      "note": "Vatikan'ın İngilizce metninde “Galatians 1:25” olarak geçen atıf (böyle bir ayet yoktur) burada Yakup 1:25 olarak düzeltilmiştir." },
    { "type": "quote",
      "tr": "“Yeni Yasa, esas olarak Mesih'e inananlara verilen Kutsal Ruh'un lütfunun ta kendisidir.” ([[Aquinolu Aziz Tomas|Saint Thomas Aquinas]])",
      "en": "“The New Law is mainly the same grace of the Holy Spirit which is given to believers in Christ.” (Saint Thomas Aquinas)" },
    { "type": "qa", "n": 421, "id": "soru-421", "ccc": "1971–1974, 1986",
      "tr": { "q": "Yeni Yasa nerede bulunur?",
              "a": "Yeni Yasa, Mesih'in bütün yaşamında ve vaazında ve havarilerin ahlaki öğretisinde bulunur. Dağdaki Vaaz onun başlıca ifadesidir." },
      "en": { "q": "Where does one find the New Law?",
              "a": "The New Law is found in the entire life and preaching of Christ and in the moral catechesis of the apostles. The Sermon on the Mount is its principal expression." } },
    { "type": "heading", "level": 4, "id": "lutuf-ve-aklanma",
      "tr": "Lütuf ve Aklanma",
      "en": "Grace and Justification" },
    { "type": "qa", "n": 422, "id": "soru-422", "ccc": "1987–1995, 2017–2020",
      "tr": { "q": "Aklanma nedir?",
              "a": "Aklanma, Tanrı sevgisinin en üstün işidir. Tanrı'nın günahlarımızı ortadan kaldıran ve bizi bütün varlığımızla doğru ve kutsal kılan merhametli ve karşılıksız eylemidir. Mesih'in çilesiyle bizim için kazanılmış ve bize Vaftiz'de verilmiş olan Kutsal Ruh'un lütfu aracılığıyla gerçekleşir. Aklanma, insanın özgür yanıtının, yani Mesih'e imanın ve Kutsal Ruh'un lütfuyla işbirliğinin başlangıcıdır." },
      "en": { "q": "What is justification?",
              "a": "Justification is the most excellent work of God's love. It is the merciful and freely-given act of God which takes away our sins and makes us just and holy in our whole being. It is brought about by means of the grace of the Holy Spirit which has been merited for us by the passion of Christ and is given to us in Baptism. Justification is the beginning of the free response of man, that is, faith in Christ and of cooperation with the grace of the Holy Spirit." } },
    { "type": "qa", "n": 423, "id": "soru-423", "ccc": "1996–1998, 2005, 2021",
      "tr": { "q": "Aklayan lütuf nedir?",
              "a": "Bu lütuf, Tanrı'nın bizi Üçlü Birlik yaşamına ortak kılmak ve O'nun sevgisiyle hareket edebilir kılmak için bize verdiği karşılıksız armağandır. Bizi kutsal kıldığı ve tanrısallaştırdığı için ona <em>sürekli, kutsallaştırıcı ya da tanrısallaştırıcı lütuf</em> denir. <em>Doğaüstüdür</em>, çünkü tümüyle Tanrı'nın karşılıksız girişimine bağlıdır ve aklın yeteneklerini ve insanların güçlerini aşar. Bu nedenle deneyimimizin dışında kalır." },
      "en": { "q": "What is the grace that justifies?",
              "a": "That grace is the gratuitous gift that God gives us to make us participants in his trinitarian life and able to act by his love. It is called <em>habitual, sanctifying or deifying grace</em> because it sanctifies and divinizes us. It is <em>supernatural</em> because it depends entirely on God’s gratuitous initiative and surpasses the abilities of the intellect and the powers of human beings. It therefore escapes our experience." } },
    { "type": "qa", "n": 424, "id": "soru-424", "ccc": "1999–2000, 2003–2004, 2023–2024",
      "tr": { "q": "Başka hangi lütuf türleri vardır?",
              "a": "Sürekli lütfun yanı sıra, etkin lütuflar (belirli durumlar için armağanlar), kutsal sır lütufları (her kutsal sırra özgü armağanlar) ve özel lütuflar ya da karizmalar (Kilise'nin ortak iyiliğine yönelik armağanlar) vardır; bunlar arasında kilise görevlerinin ve yaşam sorumluluklarının yerine getirilmesine eşlik eden durum lütufları da bulunur." },
      "en": { "q": "What other kinds of grace are there?",
              "a": "Besides habitual grace, there are actual graces (gifts for specific circumstances), sacramental graces (gifts proper to each sacrament), special graces or charisms (gifts that are intended for the common good of the Church) among which are the graces of state that accompany the exercise of ecclesial ministries and the responsibilities of life." } },
    { "type": "qa", "n": 425, "id": "soru-425", "ccc": "2001–2002",
      "tr": { "q": "Lütuf ile insan özgürlüğü arasındaki ilişki nedir?",
              "a": "Lütuf özgür yanıtımızdan önce gelir, onu hazırlar ve uyandırır. İnsan özgürlüğünün derin özlemlerine yanıt verir, onun işbirliğini ister ve özgürlüğü yetkinliğine doğru götürür." },
      "en": { "q": "What is the relationship between grace and human freedom?",
              "a": "Grace precedes, prepares and elicits our free response. It responds to the deep yearnings of human freedom, calls for its cooperation and leads freedom toward its perfection." } },
    { "type": "qa", "n": 426, "id": "soru-426", "ccc": "2006–2010, 2025–2026",
      "tr": { "q": "Hak ediş (liyakat) nedir?",
              "a": "Genel olarak hak ediş, iyi bir eylem için karşılık alma hakkını belirtir. Tanrı karşısında biz kendi başımıza hiçbir şeyi hak edemeyiz, çünkü her şeyi O'ndan karşılıksız olarak aldık. Bununla birlikte Tanrı, Tanrı önünde hak edişlerimizin kaynağı olan Mesih'in sevgisiyle birleşme yoluyla bize hak ediş kazanma olanağı verir. Bu nedenle iyi işlerin hak edişleri ilk olarak Tanrı'nın lütfuna, sonra da insanın özgür iradesine atfedilmelidir." },
      "en": { "q": "What is merit?",
              "a": "In general merit refers to the right to recompense for a good deed. With regard to God, we of ourselves are not able to merit anything, having received everything freely from him. However, God gives us the possibility of acquiring merit through union with the love of Christ, who is the source of our merits before God. The merits for good works, therefore must be attributed in the first place to the grace of God and then to the free will of man." } },
    { "type": "qa", "n": 427, "id": "soru-427", "ccc": "2010–2011, 2027",
      "tr": { "q": "Hangi nimetleri hak edebiliriz?",
              "a": "Kutsal Ruh'un etkisiyle kendimiz ve başkaları için kutsallaşmamıza ve sonsuz yaşama erişmemize gerekli lütufları hak edebiliriz. Tanrı'nın tasarısına uygun olarak bizim için yararlı olan dünyasal nimetler de hak edilebilir. Ancak hiç kimse tövbenin ve aklanmanın kökeninde bulunan <em>ilk lütfu</em> hak edemez." },
      "en": { "q": "What are the goods that we can merit?",
              "a": "Moved by the Holy Spirit, we can merit for ourselves and for others the graces needed for our sanctification and for the attainment of eternal life. Even temporal goods, suitable for us, can be merited in accordance with the plan of God. No one, however, can merit the <em>initial grace</em> which is at the origin of conversion and justification." } },
    { "type": "qa", "n": 428, "id": "soru-428", "ccc": "2012–2016, 2028–2029",
      "tr": { "q": "Herkes Hristiyan kutsallığına çağrılmış mıdır?",
              "a": "Bütün inanlılar Hristiyan kutsallığına çağrılmıştır. Bu, Hristiyan yaşamının doluluğu ve sevginin yetkinliğidir ve Mesih'le ve O'nda En Kutsal Üçlü'yle içten bir birlik yoluyla gerçekleşir. Bir Hristiyan için kutsallığa giden yol haçtan geçer ve Tanrı'nın her şeyde her şey olacağı doğruların son dirilişinde tamamlanacaktır." },
      "en": { "q": "Are all called to Christian holiness?",
              "a": "All the faithful are called to Christian holiness. This is the fullness of Christian life and the perfection of charity and it is brought about by intimate union with Christ and, in him, with the most Holy Trinity. The path to holiness for a Christian goes by way of the cross and will come to its fulfillment in the final resurrection of the just, in which God will be all in all." } },
    { "type": "heading", "level": 4, "id": "anne-ve-ogretmen-kilise",
      "tr": "Anne ve Öğretmen Kilise",
      "en": "The Church Mother and Teacher" },
    { "type": "qa", "n": 429, "id": "soru-429", "ccc": "2030–2031, 2047",
      "tr": { "q": "Kilise bir Hristiyanın ahlaki yaşamını nasıl besler?",
              "a": "Kilise, Hristiyanın Tanrı Sözü'nü, “Mesih'in Yasası”nın (Galatyalılar 6:2) öğretilerini ve kutsal sırların lütfunu aldığı topluluktur. Hristiyanlar Mesih'in Efkaristiya kurbanına öyle birleşirler ki ahlaki yaşamları ruhsal bir tapınma eylemi olur; kutsallık örneğini ise Bakire Meryem'den ve Azizlerin yaşamlarından öğrenirler." },
      "en": { "q": "How does the Church nourish the moral life of a Christian?",
              "a": "The Church is the community in which the Christian receives the Word of God, the teachings of the “Law of Christ” (<em>Galatians</em> 6:2), and the grace of the sacraments. Christians are united to the Eucharistic sacrifice of Christ in such a way that their moral life is an act of spiritual worship; and they learn the example of holiness from the Virgin Mary and the lives of the Saints." } },
    { "type": "qa", "n": 430, "id": "soru-430", "ccc": "2032–2040, 2049–2051",
      "tr": { "q": "Kilise'nin Öğretim Makamı neden ahlak alanında etkinlik gösterir?",
              "a": "İnanılması ve yaşamda uygulanması gereken imanı vaaz etmek Kilise'nin Öğretim Makamı'nın görevidir. Bu görev, doğal yasanın belirli buyruklarını da kapsar; çünkü onlara uyulması kurtuluş için gereklidir." },
      "en": { "q": "Why does the Magisterium of the Church act in the field of morality?",
              "a": "It is the duty of the Magisterium of the Church to preach the faith that is to be believed and put into practice in life. This duty extends even to the specific precepts of the natural law because their observance is necessary for salvation." } },
    { "type": "qa", "n": 431, "id": "soru-431", "ccc": "2041, 2048",
      "tr": { "q": "Kilise'nin buyruklarının amacı nedir?",
              "a": "Kilise'nin beş buyruğu, inanlılar için dua ruhunda, kutsal sır yaşamında, ahlaki bağlılıkta ve Tanrı ve komşu sevgisinde büyümede vazgeçilmez asgariyi güvence altına almayı amaçlar." },
      "en": { "q": "What purpose do the precepts of the Church have?",
              "a": "The five precepts of the Church are meant to guarantee for the faithful the indispensable minimum in the spirit of prayer, the sacramental life, moral commitment and growth in love of God and neighbor." } },
    { "type": "qa", "n": 432, "id": "soru-432", "ccc": "2042–2043",
      "tr": { "q": "Kilise'nin buyrukları nelerdir?",
              "a": "Bunlar şunlardır: 1) Pazar günleri ve diğer zorunlu kutsal bayram günlerinde Ayin'e katılmak ve bu günlerin kutsal kılınmasını engelleyebilecek iş ve etkinliklerden kaçınmak; 2) en az yılda bir kez Barışma sırrını alarak günahlarını itiraf etmek; 3) en azından Paskalya döneminde Efkaristiya sırrını almak; 4) Kilise'nin belirlediği günlerde et yemekten kaçınmak ve oruç günlerine uymak; ve 5) her biri kendi olanakları ölçüsünde Kilise'nin maddi ihtiyaçlarının karşılanmasına yardım etmek." },
      "en": { "q": "What are the precepts of the Church?",
              "a": "They are: 1) to attend Mass on Sundays and other holy days of obligation and to refrain from work and activities which could impede the sanctification of those days; 2) to confess one's sins, receiving the sacrament of Reconciliation at least once each year; 3) to receive the sacrament of the Eucharist at least during the Easter season; 4) to abstain from eating meat and to observe the days of fasting established by the Church; and 5) to help to provide for the material needs of the Church, each according to his own ability." } },
    { "type": "qa", "n": 433, "id": "soru-433", "ccc": "2044–2046",
      "tr": { "q": "Hristiyan ahlaki yaşamı Müjde'nin duyurulması için neden vazgeçilmezdir?",
              "a": "Çünkü yaşamları Rab İsa'ya uygun kılınmış olan Hristiyanlar, başkalarını gerçek Tanrı'ya imana çeker, Kilise'yi bina eder, dünyayı Müjde'nin ruhuyla biçimlendirir ve Tanrı'nın Egemenliği'nin gelişini hızlandırırlar." },
      "en": { "q": "Why is the Christian moral life indispensable for the proclamation of the Gospel?",
              "a": "Because their lives are conformed to the Lord Jesus, Christians draw others to faith in the true God, build up the Church, inform the world with the spirit of the Gospel, and hasten the coming of the Kingdom of God." } },
    { "type": "heading", "level": 2, "id": "ikinci-bolum-on-emir",
      "tr": "İkinci Bölüm: On Emir",
      "en": "Section Two: The Ten Commandments" },
    { "type": "special", "ref": "decalogue" },
    { "type": "qa", "n": 434, "id": "soru-434", "ccc": "2052–2054, 2075–2076",
      "tr": { "q": "“Öğretmenim, sonsuz yaşama kavuşmak için ne iyilik yapmalıyım?” (Matta 19:16)",
              "a": "Bu soruyu soran gence İsa şöyle yanıt verdi: “Yaşama kavuşmak istiyorsan, buyrukları yerine getir”; sonra da şunu ekledi: “Gel, beni izle” (Matta 19:16-21). İsa'yı izlemek buyrukları yerine getirmeyi içerir. Yasa kaldırılmamıştır; ama insan onu, Yasa'yı Kendisinde yetkin biçimde gerçekleştiren, onun tam anlamını açıklayan ve kalıcı geçerliliğine tanıklık eden tanrısal Öğretmen'in Kişisi'nde yeniden keşfetmeye davet edilir." },
      "en": { "q": "“Teacher, what good must I do to have eternal life?” (<em>Matthew</em> 19:16).",
              "a": "To the young man who asked this question, Jesus answered, “If you would enter into life, keep the commandments”, and then he added, “Come, follow Me” (<em>Matthew</em> 19:16-21). To follow Jesus involves keeping the commandments. The law has not been abolished but man is invited to rediscover it in the Person of the divine Master who realized it perfectly in himself, revealed its full meaning and attested to its permanent validity." } },
    { "type": "qa", "n": 435, "id": "soru-435", "ccc": "2055",
      "tr": { "q": "İsa Yasa'yı nasıl yorumladı?",
              "a": "İsa Yasa'yı, Yasa'nın doluluğu olan ikili ama tek sevgi buyruğunun ışığında yorumladı: “Tanrın Rab'bi bütün yüreğinle, bütün canınla ve bütün aklınla seveceksin. İşte ilk ve en önemli buyruk budur. İkincisi de buna benzer: Komşunu kendin gibi seveceksin. Kutsal Yasa'nın tamamı ve peygamberlerin sözleri bu iki buyruğa dayanır” (Matta 22:37-40)." },
      "en": { "q": "How did Jesus interpret the Law?",
              "a": "Jesus interpreted the Law in the light of the twofold yet single commandment of love, the fullness of the Law: “You shall love the Lord your God with all your heart and with all your soul and with all your mind. This is the greatest and first commandment. And the second is like it: you shall love your neighbor as yourself. On these two commandments depend all the Law and the Prophets” (<em>Matthew</em> 22:37-40)." } },
    { "type": "qa", "n": 436, "id": "soru-436", "ccc": "2056–2057",
      "tr": { "q": "“Dekalog” ne anlama gelir?",
              "a": "Dekalog “on söz” anlamına gelir (Çıkış 34:28). Bu sözler, Musa'nın aracılık ettiği Antlaşma bağlamında Tanrı'nın İsrail halkına verdiği Yasa'yı özetler. Tanrı sevgisinin buyruklarını (ilk üçü) ve komşu sevgisinin buyruklarını (diğer yedisi) sunan bu Dekalog, seçilmiş halk ve özellikle her insan için günahın köleliğinden kurtulmuş bir yaşamın yolunu çizer." },
      "en": { "q": "What does “Decalogue” mean?",
              "a": "Decalogue means “ten words” (<em>Exodus</em> 34:28). These words sum up the Law given by God to the people of Israel in the context of the Covenant mediated by Moses. This Decalogue, in presenting the commandments of the love of God (the first three) and of one's neighbor (the other seven), traces for the chosen people and for every person in particular the path to a life freed from the slavery of sin." } },
    { "type": "qa", "n": 437, "id": "soru-437", "ccc": "2058–2063, 2077",
      "tr": { "q": "Dekalog ile Antlaşma arasındaki bağ nedir?",
              "a": "Dekalog, Tanrı'nın Kendini açıkladığı ve isteğini bildirdiği Antlaşma'nın ışığında anlaşılmalıdır. Buyruklara uyarak halk Tanrı'ya ait olduğunu gösterdi ve O'nun sevgi girişimine şükranla yanıt verdi." },
      "en": { "q": "What is the bond between the Decalogue and the Covenant?",
              "a": "The Decalogue must be understood in the light of the Covenant in which God revealed himself and made known his will. In observing the commandments, the people manifested their belonging to God and they answered his initiative of love with thanksgiving." } },
    { "type": "qa", "n": 438, "id": "soru-438", "ccc": "2064–2068",
      "tr": { "q": "Kilise Dekalog'a ne önem verir?",
              "a": "Kilise, Kutsal Yazı'ya ve Mesih'in örneğine sadık kalarak Dekalog'un temel önemini ve anlamını kabul eder. Hristiyanlar ona uymakla yükümlüdür." },
      "en": { "q": "What importance does the Church give to the Decalogue?",
              "a": "The Church, in fidelity to Scripture and to the example of Christ, acknowledges the primordial importance and significance of the Decalogue. Christians are obliged to keep it." } },
    { "type": "qa", "n": 439, "id": "soru-439", "ccc": "2069, 2079",
      "tr": { "q": "Dekalog neden organik bir birlik oluşturur?",
              "a": "On Emir organik ve bölünmez bir bütün oluşturur; çünkü her buyruk diğer buyruklara ve bütün Dekalog'a gönderme yapar. Bu nedenle bir buyruğu çiğnemek bütün yasayı çiğnemek demektir." },
      "en": { "q": "Why does the Decalogue constitute an organic unity?",
              "a": "The Ten Commandments form an organic and indivisible whole because each commandment refers to the other commandments and to the entire Decalogue. To break one commandment, therefore, is to violate the entire law." } },
    { "type": "qa", "n": 440, "id": "soru-440", "ccc": "2072–2073, 2081",
      "tr": { "q": "Dekalog neden ağır yükümlülükler getirir?",
              "a": "Bunu yapar, çünkü Dekalog insanın Tanrı'ya ve komşusuna karşı temel görevlerini ifade eder." },
      "en": { "q": "Why does the Decalogue enjoin serious obligations?",
              "a": "It does so because the Decalogue expresses the fundamental duties of man towards God and towards his neighbor." } },
    { "type": "qa", "n": 441, "id": "soru-441", "ccc": "2074, 2082",
      "tr": { "q": "Dekalog'a uymak mümkün müdür?",
              "a": "Evet, çünkü O'nsuz hiçbir şey yapamayacağımız Mesih, Ruhu'nun ve lütfunun armağanıyla ona uymamızı mümkün kılar." },
      "en": { "q": "Is it possible to keep the Decalogue?",
              "a": "Yes, because Christ without whom we can do nothing enables us to keep it with the gift of his Spirit and his grace." } },
    { "type": "heading", "level": 3, "id": "birinci-baslik-tanrin-rabbi-butun-yureginle-butun-caninla",
      "tr": "Birinci Başlık: “Tanrın Rab'bi Bütün Yüreğinle, Bütün Canınla ve Bütün Aklınla Seveceksin”",
      "en": "Chapter One: “You Shall Love the Lord Your God With All Your Heart, With All Your Soul, and With All Your Mind”" },
    { "type": "heading", "level": 4, "id": "birinci-emir-tanrin-rab-benim-benden-baska-tanrin-olmayacak",
      "tr": "Birinci Emir: Tanrın Rab Ben'im; Benden Başka Tanrın Olmayacak",
      "en": "The First Commandment: I Am the Lord your God, You Shall not Have Other Gods before Me" },
    { "type": "qa", "n": 442, "id": "soru-442", "ccc": "2083–2094, 2133–2134",
      "tr": { "q": "Tanrı'nın “Tanrın Rab Ben'im” (Çıkış 20:2) onaylaması neyi içerir?",
              "a": "Bu, inanlıların üç tanrısal erdemi korumaları ve etkin kılmaları ve bunlara karşıt olan günahlardan kaçınmaları gerektiği anlamına gelir. <em>İman</em> Tanrı'ya inanır ve ona karşıt olan her şeyi, örneğin bilinçli kuşkuyu, imansızlığı, sapkınlığı (heresi), dinden dönmeyi (irtidat) ve bölücülüğü (şizma) reddeder. <em>Umut</em>, umutsuzluktan ve kendini beğenmiş güvenden (küstah güven) kaçınarak Tanrı'nın mutlu görümünü ve yardımını güvenle bekler. <em>Sevgi</em> Tanrı'yı her şeyden çok sever ve bu nedenle kayıtsızlığı, nankörlüğü, ılıklığı, ruhsal tembelliği (acedia) ve gururdan doğan Tanrı nefretini reddeder." },
      "en": { "q": "What is implied in the affirmation of God: “I am the Lord your God” (<em>Exodus</em> 20:2)?",
              "a": "This means that the faithful must guard and activate the three theological virtues and must avoid sins which are opposed to them. <em>Faith</em> believes in God and rejects everything that is opposed to it, such as, deliberate doubt, unbelief, heresy, apostasy, and schism. <em>Hope</em> trustingly awaits the blessed vision of God and his help, while avoiding despair and presumption. <em> Charity</em> loves God above all things and therefore repudiates indifference, ingratitude, lukewarmness, sloth or spiritual indolence, and that hatred of God which is born of pride." } },
    { "type": "qa", "n": 443, "id": "soru-443", "ccc": "2095–2105, 2135–2136",
      "tr": { "q": "Rabbimizin “Tanrın Rab'be tapınacak, yalnız O'na kulluk edeceksin” (Matta 4:10) sözlerinin anlamı nedir?",
              "a": "Bu sözler, Tanrı'ya var olan her şeyin Rabbi olarak tapınmak; O'na yaraşan bireysel ve toplu tapınmayı sunmak; O'na övgü, şükran ve yakarış duygularıyla dua etmek; O'na kurbanlar, her şeyden önce Mesih'in yetkin kurbanıyla birleşmiş olarak kişinin kendi yaşamının ruhsal kurbanını sunmak; ve O'na verilen sözleri ve adakları yerine getirmek anlamına gelir." },
      "en": { "q": "What is the meaning of the words of our Lord, “Adore the Lord your God and worship Him alone” (<em>Matthew</em> 4:10)?",
              "a": "These words mean to adore God as the Lord of everything that exists; to render to him the individual and community worship which is his due; to pray to him with sentiments of praise, of thanks, and of supplication; to offer him sacrifices, above all the spiritual sacrifice of one’s own life, united with the perfect sacrifice of Christ; and to keep the promises and vows made to him." } },
    { "type": "qa", "n": 444, "id": "soru-444", "ccc": "2104–2109, 2137",
      "tr": { "q": "Kişi Tanrı'ya gerçekte ve özgürlük içinde tapınma hakkını nasıl kullanır?",
              "a": "Her insanın, özellikle Tanrı'yı ve O'nun Kilisesi'ni ilgilendiren konularda gerçeği arama hakkı ve ahlaki görevi vardır. Gerçek bilindiğinde, her insanın onu benimseme, sadakatle koruma ve Tanrı'ya sahih bir tapınma sunma hakkı ve ahlaki görevi vardır. Aynı zamanda insan kişisinin onuru, dinsel konularda hiç kimsenin vicdanına aykırı davranmaya zorlanmamasını ve kamu düzeninin adil sınırları içinde, özel ya da kamusal olarak, tek başına ya da başkalarıyla birlikte vicdanına uygun davranmaktan alıkonulmamasını gerektirir." },
      "en": { "q": "In what way does a person exercise his or her proper right to worship God in truth and in freedom?",
              "a": "Every person has the right and the moral duty to seek the truth, especially in what concerns God and his Church. Once the truth is known, each person he has the right and moral duty to embrace it, to guard it faithfully and to render God authentic worship. At the same time, the dignity of the human person requires that in religious matters no one may be forced to act against conscience nor be restrained, within the just limits of public order, from acting in conformity with conscience, privately or publicly, alone or in association with others." } },
    { "type": "qa", "n": 445, "id": "soru-445", "ccc": "2110–2128, 2138–2140",
      "tr": { "q": "Tanrı “Benden başka tanrın olmayacak” (Çıkış 20:2) buyruğuyla neyi yasaklar?",
              "a": "Bu buyruk şunları yasaklar:\n- Yaratıkları, gücü, parayı, hatta iblisleri tanrılaştıran <em>çok tanrıcılık</em> ve <em>putperestlik</em>.\n- Gerçek Tanrı'ya yaraşan tapınmadan sapma olan ve kendini çeşitli falcılık, büyü, sihirbazlık ve ruh çağırma (spiritizm) biçimlerinde de gösteren <em>batıl inanç</em>.\n- Tanrı'yı sözle ya da eylemle sınamada; kutsal kişilere ya da kutsal şeylere, her şeyden önce Efkaristiya'ya saygısızlık eden kutsala saygısızlıkta (sakrilej); ve ruhsal şeylerin alınıp satılmasını içeren simoniyle kendini gösteren <em>dinsizlik</em>.\n- Çoğu zaman insan özerkliğine ilişkin yanlış bir anlayışa dayanan ve Tanrı'nın varlığını reddeden <em>ateizm</em>.\n- Tanrı hakkında hiçbir şeyin bilinemeyeceğini ileri süren ve kayıtsızlığı ve pratik ateizmi içeren <em>agnostisizm</em> (bilinemezcilik)." },
      "en": { "q": "What does God prohibit by his command, “You shall not have other gods before me” (<em>Exodus</em> 20:2)?",
              "a": "This commandment forbids:\n- <em>Polytheism</em> and <em>idolatry</em>, which divinizes creatures, power, money, or even demons.\n- <em>Superstition</em> which is a departure from the worship due to the true God and which also expresses itself in various forms of divination, magic, sorcery and spiritism.\n- <em>Irreligion</em> which is evidenced: in tempting God by word or deed; in sacrilege, which profanes sacred persons or sacred things, above all the Eucharist; and in simony, which involves the buying or selling of spiritual things.\n- <em>Atheism</em> which rejects the existence of God, founded often on a false conception of human autonomy.\n- <em>Agnosticism</em> which affirms that nothing can be known about God, and involves indifferentism and practical atheism." } },
    { "type": "qa", "n": 446, "id": "soru-446", "ccc": "2129–2132, 2141",
      "tr": { "q": "Tanrı'nın “Kendine oyma put yapmayacaksın” (Çıkış 20:3) buyruğu tasvirlere saygıyı yasaklar mı?",
              "a": "Eski Antlaşma'da bu buyruk mutlak olarak aşkın olan Tanrı'nın her türlü betimlemesini yasaklıyordu. Ancak kutsal tasvirlere Hristiyan saygısı Tanrı Oğlu'nun beden almasıyla haklı çıkar ([[II. İznik|Second Council of Nicaea]] Konsili'nin, MS 787'de öğrettiği gibi); çünkü bu saygı, aşkın Tanrı'nın Kendisinde görünür kılındığı, insan olmuş Tanrı Oğlu'nun gizemine dayanır. Bu bir tasvire tapınmak değil, onda betimlenen kişiye saygı göstermek demektir: örneğin Mesih'e, Kutsal Bakire Meryem'e, Meleklere ve Azizlere." },
      "en": { "q": "Does the commandment of God, “You shall not make for yourself a graven image” (<em>Exodus</em> 20:3), forbid the cult of images?",
              "a": "In the Old Testament this commandment forbade any representation of God who is absolutely transcendent. The Christian veneration of sacred images, however, is justified by the incarnation of the Son of God (as taught by the Second Council of Nicea in 787AD) because such veneration is founded on the mystery of the Son of God made man, in whom the transcendent God is made visible. This does not mean the adoration of an image, but rather the veneration of the one who is represented in it: for example, Christ, the Blessed Virgin Mary, the Angels and the Saints." } },
    { "type": "heading", "level": 4, "id": "ikinci-emir-tanrin-rabbin-adini-bos-yere-agzina-almayacaksin",
      "tr": "İkinci Emir: Tanrın Rab'bin Adını Boş Yere Ağzına Almayacaksın",
      "en": "The Second Commandment: You Shall not Take the Name of the Lord your God in Vain" },
    { "type": "qa", "n": 447, "id": "soru-447", "ccc": "2142–2149, 2160–2162",
      "tr": { "q": "Tanrı'nın Adı'nın kutsallığına nasıl saygı gösterilir?",
              "a": "Tanrı'nın kutsal Adı'na, onu kutsayarak, överek ve yücelterek saygı gösterilir. Bu nedenle bir suçu haklı çıkarmak için Tanrı'nın Adı'nı anmak yasaktır. Tanrı'nın kutsal Adı'nı herhangi bir uygunsuz biçimde kullanmak da yanlıştır: <em>küfür</em> (doğası gereği ağır bir günahtır), <em>lanet okuma</em> ve Tanrı'nın Adı'yla verilen sözlere <em>sadakatsizlik</em> gibi." },
      "en": { "q": "How does one respect the holiness of the Name of God?",
              "a": "One shows respect for the holy Name of God by blessing it, praising it and glorifying it. It is forbidden, therefore, to call on the Name of God to justify a crime. It is also wrong to use the holy Name of God in any improper way as in <em>blasphemy</em> (which by its nature is a grave sin), <em>curses</em>, and <em> unfaithfulness</em> to promises made in the Name of God." } },
    { "type": "qa", "n": 448, "id": "soru-448", "ccc": "2150–2151, 2163–2164",
      "tr": { "q": "Yalan yere yemin neden yasaktır?",
              "a": "Yasaktır, çünkü kişi Gerçeğin Kendisi olan Tanrı'yı bir yalana tanık olarak çağırır." },
      "en": { "q": "Why is a false oath forbidden?",
              "a": "It is forbidden because one calls upon God who is truth itself to be the witness to a lie." } },
    { "type": "quote",
      "tr": "“Ne Yaratıcı ne de herhangi bir yaratık üzerine yemin etme; ancak doğrulukla, zorunlulukla ve saygıyla yemin et.” ([[Loyolalı Aziz İgnatius|Saint Ignatius of Loyola]])",
      "en": "“Do not swear, whether by the Creator or by any creature, except truthfully, of necessity and with reverence.” (Saint Ignatius of Loyola)" },
    { "type": "qa", "n": 449, "id": "soru-449", "ccc": "2152–2155",
      "tr": { "q": "Yeminini bozma (yalan yere yemin) nedir?",
              "a": "Yeminini bozma, yemin altında yerine getirmeme niyetiyle bir söz vermek ya da yemin altında verilmiş bir sözü çiğnemektir. Vaatlerine her zaman sadık olan Tanrı'ya karşı ağır bir günahtır." },
      "en": { "q": "What is perjury?",
              "a": "Perjury is to make a promise under oath with the intention of not keeping it or to violate a promise made under oath. It is a grave sin against God who is always faithful to his promises." } },
    { "type": "heading", "level": 4, "id": "ucuncu-emir-rabbin-gununu-kutsal-tutmayi-unutma",
      "tr": "Üçüncü Emir: Rab'bin Gününü Kutsal Tutmayı Unutma",
      "en": "The Third Commandment: Remember to Keep Holy the Lord's Day" },
    { "type": "qa", "n": 450, "id": "soru-450", "ccc": "2168–2172, 2189",
      "tr": { "q": "Tanrı neden “Şabat gününü kutsadı ve onu kutsal kıldı” (Çıkış 20:11)?",
              "a": "Tanrı bunu yaptı, çünkü Şabat günü, yaratılışın yedinci gününde <em>Tanrı'nın dinlenişi</em>, ayrıca İsrail'in [[Mısır'daki|Egypt]] kölelikten kurtuluşu ve Tanrı'nın halkıyla mühürlediği Antlaşma anılır." },
      "en": { "q": "Why did God “bless the Sabbath day and declare it sacred” (<em>Exodus</em> 20:11)?",
              "a": "God did so because on the Sabbath day one remembers <em>God’s rest</em> on the seventh day of creation, and also the liberation of Israel from slavery in Egypt and the Covenant which God sealed with his people." } },
    { "type": "qa", "n": 451, "id": "soru-451", "ccc": "2173",
      "tr": { "q": "İsa Şabat konusunda nasıl davrandı?",
              "a": "İsa Şabat gününün kutsallığını tanıdı ve tanrısal yetkiyle bu yasaya sahih yorumunu verdi: “Şabat insan için yapıldı, insan Şabat için yapılmadı” (Markos 2:27)." },
      "en": { "q": "How did Jesus act in regard to the Sabbath?",
              "a": "Jesus recognized the holiness of the Sabbath day and with divine authority he gave this law its authentic interpretation: “The Sabbath was made for man, and not man for the sabbath” (<em>Mark</em> 2:27)." } },
    { "type": "qa", "n": 452, "id": "soru-452", "ccc": "2174–2176, 2190–2191",
      "tr": { "q": "Hristiyanlar için Şabat hangi nedenle Pazar gününe dönüşmüştür?",
              "a": "Nedeni, Pazar gününün Mesih'in Dirilişi'nin günü olmasıdır. “Haftanın ilk günü” (Markos 16:2) olarak ilk yaratılışı hatırlatır; Şabat'ı izleyen “sekizinci gün” olarak ise Mesih'in Dirilişi'yle başlayan yeni yaratılışı simgeler. Böylece Hristiyanlar için bütün günlerin ve bütün bayramların ilki olmuştur. O, Rab'bin Paskalyasıyla Yahudi Şabatı'nın ruhsal gerçeğini yerine getirdiği ve insanın Tanrı'daki sonsuz dinlenişini duyurduğu <em>Rab'bin Günü</em>'dür." },
      "en": { "q": "For what reason has the Sabbath been changed to Sunday for Christians?",
              "a": "The reason is because Sunday is the day of the Resurrection of Christ. As “the first day of the week” (<em>Mark</em> 16:2) it recalls the first creation; and as the “eighth day”, which follows the sabbath, it symbolizes the new creation ushered in by the Resurrection of Christ. Thus, it has become for Christians the first of all days and of all feasts. It is the <em>day of the Lord</em> in which he with his Passover fulfilled the spiritual truth of the Jewish Sabbath and proclaimed man’s eternal rest in God." } },
    { "type": "qa", "n": 453, "id": "soru-453", "ccc": "2177–2185, 2192–2193",
      "tr": { "q": "Pazar günü nasıl kutsal tutulur?",
              "a": "Hristiyanlar Pazar gününü ve diğer zorunlu kutsal günleri, Rab'bin Efkaristiya'sına katılarak ve Tanrı'ya tapınmayı engelleyen ve Rab'bin gününe özgü sevinci ya da zihnin ve bedenin gerekli dinlenmesini bozan etkinliklerden kaçınarak kutsal tutarlar. Aile ihtiyaçlarıyla ya da önemli toplumsal hizmetle bağlantılı etkinliklere, Pazar gününün kutsallığına, aile yaşamına ve sağlığa zarar veren alışkanlıklara yol açmamaları koşuluyla izin verilir." },
      "en": { "q": "How does one keep Sunday holy?",
              "a": "Christians keep Sunday and other days of obligation holy by participating in the Eucharist of the Lord and by refraining from those activities which impede the worship of God and disturb the joy proper to the day of the Lord or the necessary relaxation of mind and body. Activities are allowed on the Sabbath which are bound up with family needs or with important social service, provided that they do not lead to habits prejudicial to the holiness of Sunday, to family life and to health." } },
    { "type": "qa", "n": 454, "id": "soru-454", "ccc": "2186–2188, 2194–2195",
      "tr": { "q": "Pazar gününün resmi tatil olarak tanınması neden önemlidir?",
              "a": "Herkese dinsel, ailevi, kültürel ve toplumsal yaşamlarıyla ilgilenebilmeleri için yeterli dinlenme ve boş zaman bulma olanağının gerçekten verilmesi açısından önemlidir. Ayrıca derin düşünce, tefekkür, sessizlik ve çalışma için uygun bir zamana ve iyi işlere, özellikle hastalar ve yaşlılar için ayrılacak bir zamana sahip olmak açısından da önemlidir." },
      "en": { "q": "Why is the civil recognition of Sunday as a feast day important?",
              "a": "It is important so that all might be given the real possibility of enjoying sufficient rest and leisure to take care of their religious, familial, cultural and social lives. It is important also to have an opportune time for meditation, for reflection, for silence, for study, and a time to dedicate to good works, particularly for the sick and for the elderly." } },
    { "type": "heading", "level": 3, "id": "ikinci-baslik-komsunu-kendin-gibi-seveceksin",
      "tr": "İkinci Başlık: “Komşunu Kendin Gibi Seveceksin”",
      "en": "Chapter Two: “You Shall Love Your Neighbour as Yourself”" },
    { "type": "heading", "level": 4, "id": "dorduncu-emir-annene-ve-babana-saygi-goster",
      "tr": "Dördüncü Emir: Annene ve Babana Saygı Göster",
      "en": "The Fourth Commandment: Honor your Father and your Mother" },
    { "type": "qa", "n": 455, "id": "soru-455", "ccc": "2196–2200, 2247–2248",
      "tr": { "q": "Dördüncü emir neyi gerektirir?",
              "a": "Anne babamıza ve Tanrı'nın, bizim iyiliğimiz için Kendi yetkisiyle donattığı kişilere saygı göstermemizi ve onları onurlandırmamızı buyurur." },
      "en": { "q": "What does the fourth commandment require?",
              "a": "It commands us to honor and respect our parents and those whom God, for our good, has vested with his authority." } },
    { "type": "qa", "n": 456, "id": "soru-456", "ccc": "2201–2205, 2249",
      "tr": { "q": "Tanrı'nın tasarısında ailenin doğası nedir?",
              "a": "Evlilikte birleşen bir erkek ve bir kadın, çocuklarıyla birlikte bir aile oluştururlar. Tanrı aileyi kurdu ve onu temel yapısıyla donattı. Evlilik ve aile, eşlerin iyiliğine ve çocukların doğurulmasına ve eğitimine yöneliktir. Aynı ailenin üyeleri kendi aralarında kişisel ilişkiler ve temel sorumluluklar kurarlar. Mesih'te aile <em>ev kilisesi</em> olur; çünkü bir iman, umut ve sevgi topluluğudur." },
      "en": { "q": "What is the nature of the family in the plan of God?",
              "a": "A man and a woman united in marriage form a family together with their children. God instituted the family and endowed it with its fundamental constitution. Marriage and the family are ordered to the good of the spouses and to the procreation and education of children. Members of the same family establish among themselves personal relationships and primary responsibilities. In Christ the family becomes the <em>domestic church</em> because it is a community of faith, of hope, and of charity." } },
    { "type": "qa", "n": 457, "id": "soru-457", "ccc": "2207–2208",
      "tr": { "q": "Aile toplumda nasıl bir yer tutar?",
              "a": "Aile insan toplumunun kökendeki hücresidir ve bu nedenle kamu otoritesinin her türlü tanımasından önce gelir. Aile değerleri ve ilkeleri toplumsal yaşamın temelini oluşturur. Aile yaşamı toplum yaşamına bir hazırlıktır." },
      "en": { "q": "What place does the family occupy in society?",
              "a": "The family is the original cell of human society and is, therefore, prior to any recognition by public authority. Family values and principles constitute the foundation of social life. Family life is an initiation into the life of society." } },
    { "type": "qa", "n": 458, "id": "soru-458", "ccc": "2209–2213, 2250",
      "tr": { "q": "Toplumun aileye karşı görevleri nelerdir?",
              "a": "Toplum, yerellik ilkesine saygı göstererek evliliği ve aileyi destekleme ve güçlendirme görevine sahiptir. Kamu otoritesi evliliğin ve ailenin gerçek doğasına, kamu ahlakına, anne babaların haklarına ve ev refahına saygı göstermeli, bunları korumalı ve desteklemelidir." },
      "en": { "q": "What are the duties that society has toward the family?",
              "a": "Society, while respecting the principle of subsidiarity, has the duty to support and strengthen marriage and the family. Public authority must respect, protect and foster the true nature of marriage and the family, public morality, the rights of parents, and domestic prosperity." } },
    { "type": "qa", "n": 459, "id": "soru-459", "ccc": "2214–2220, 2251",
      "tr": { "q": "Çocukların anne babalarına karşı görevleri nelerdir?",
              "a": "Çocuklar anne babalarına saygı (evlat sevgisi), minnet, uysallık ve itaat borçludur. Onlara saygı göstererek ve kardeşleriyle iyi ilişkiler geliştirerek çocuklar genel olarak aile yaşamında uyumun ve kutsallığın büyümesine katkıda bulunurlar. Yetişkin çocuklar, anne babaları sıkıntı, hastalık, yalnızlık ya da yaşlılık durumlarında olduklarında onlara maddi ve manevi destek vermelidir." },
      "en": { "q": "What are the duties of children toward their parents?",
              "a": "Children owe respect (filial piety), gratitude, docility and obedience to their parents. In paying them respect and in fostering good relationships with their brothers and sisters, children contribute to the growth in harmony and holiness in family life in general. Adult children should give their parents material and moral support whenever they find themselves in situations of distress, sickness, loneliness, or old age." } },
    { "type": "qa", "n": 460, "id": "soru-460", "ccc": "2221–2231",
      "tr": { "q": "Anne babaların çocuklarına karşı görevleri nelerdir?",
              "a": "Anne babalar, Tanrı'nın babalığına katılımları sayesinde çocuklarının eğitiminin ilk sorumlusudur ve onlar için imanın ilk müjdecileridir. Çocuklarını <em>kişiler</em> ve <em>Tanrı'nın çocukları</em> olarak sevme ve onlara saygı gösterme ve olanaklar ölçüsünde onların bedensel ve ruhsal ihtiyaçlarını karşılama görevine sahiptirler. Onlar için uygun bir okul seçmeli ve meslek ve yaşam durumu seçiminde onlara sağduyulu öğütlerle yardım etmelidirler. Özellikle çocuklarını Hristiyan imanında eğitme görevine sahiptirler." },
      "en": { "q": "What are the duties of parents toward their children?",
              "a": "Parents, in virtue of their participation in the fatherhood of God, have the first responsibility for the education of their children and they are the first heralds of the faith for them. They have the duty to love and respect their children as <em>persons</em> and as <em>children of God</em> and to provide, as far as is possible, for their physical and spiritual needs. They should select for them a suitable school and help them with prudent counsel in the choice of their profession and their state of life. In particular they have the mission of educating their children in the Christian faith." } },
    { "type": "qa", "n": 461, "id": "soru-461", "ccc": "2252–2253",
      "tr": { "q": "Anne babalar çocuklarını Hristiyan imanında nasıl eğitmelidir?",
              "a": "Anne babalar bunu esas olarak örnek olarak, dua ederek, aile içinde din eğitimi vererek ve Kilise'nin yaşamına katılarak yaparlar." },
      "en": { "q": "How are parents to educate their children in the Christian faith?",
              "a": "Parents do this mainly by example, prayer, family catechesis and participation in the life of the Church." } },
    { "type": "qa", "n": 462, "id": "soru-462", "ccc": "2232–2233",
      "tr": { "q": "Aile bağları mutlak bir iyilik midir?",
              "a": "Aile bağları önemlidir ama mutlak değildir; çünkü bir Hristiyanın ilk çağrısı İsa'yı izlemek ve O'nu sevmektir: “Annesini ya da babasını benden çok seven bana layık değildir. Oğlunu ya da kızını benden çok seven bana layık değildir” (Matta 10:37). Anne babalar çocuklarının hangi yaşam durumunda olursa olsun, kutsanmış yaşamda ya da rahiplik görevinde bile, İsa'yı izleme seçimini sevinçle desteklemelidir." },
      "en": { "q": "Are family bonds an absolute good?",
              "a": "Family ties are important but not absolute, because the first vocation of a Christian is to follow Jesus and love him: “He who loves father or mother more than me is not worthy of me; whoever loves son or daughter more than me is not worthy of me” (<em>Matthew</em> 10:37). Parents must support with joy their children's choice to follow Jesus in whatever state of life, even in the consecrated life or the priestly ministry." } },
    { "type": "qa", "n": 463, "id": "soru-463", "ccc": "2234–2237, 2254",
      "tr": { "q": "Sivil toplumun çeşitli alanlarında otorite nasıl kullanılmalıdır?",
              "a": "Otorite her zaman bir hizmet olarak, temel insan haklarına, değerlerin adil sıralamasına, yasalara, dağıtıcı adalete ve yerellik ilkesine saygı gösterilerek kullanılmalıdır. Otorite kullanan herkes topluluğun çıkarlarını kendi çıkarından önce gözetmeli ve kararlarının Tanrı, insan ve dünya hakkındaki gerçekten esinlenmesine izin vermelidir." },
      "en": { "q": "How should authority be exercised in the various spheres of civil society?",
              "a": "Authority should always be exercised as a service, respecting fundamental human rights, a just hierarchy of values, laws, distributive justice, and the principle of subsidiarity. All those who exercise authority should seek the interests of the community before their own interest and allow their decisions to be inspired by the truth about God, about man and about the world." } },
    { "type": "qa", "n": 464, "id": "soru-464", "ccc": "2238–2241, 2255",
      "tr": { "q": "Yurttaşların sivil otoritelere karşı görevleri nelerdir?",
              "a": "Otoriteye bağlı olanlar, otorite sahiplerini Tanrı'nın temsilcileri olarak görmeli ve kamusal ve toplumsal yaşamın doğru işleyişi için onlarla sadakatle işbirliği yapmalıdır. Bu işbirliği, yurda sevgiyi ve hizmeti, oy verme hakkını ve görevini, vergilerin ödenmesini, ülkenin savunulmasını ve yapıcı eleştiri hakkını içerir." },
      "en": { "q": "What are the duties of citizens in regard to civil authorities?",
              "a": "Those subject to authority should regard those in authority as representatives of God and offer their loyal collaboration for the right functioning of public and social life. This collaboration includes love and service of one's homeland, the right and duty to vote, payment of taxes, the defense of one's country, and the right to exercise constructive criticism." } },
    { "type": "qa", "n": 465, "id": "soru-465", "ccc": "2242–2243, 2256",
      "tr": { "q": "Bir yurttaşın sivil otoritelere itaat etmesi ne zaman yasaktır?",
              "a": "Bir yurttaş, sivil otoritelerin yasaları ahlak düzeninin gereklerine aykırı olduğunda bu yasalara uymamakla vicdanen yükümlüdür: “İnsanlardan çok Tanrı'ya itaat etmeliyiz” (Elçilerin İşleri 5:29)." },
      "en": { "q": "When is a citizen forbidden to obey civil authorities?",
              "a": "A citizen is obliged in conscience not to obey the laws of civil authorities when they are contrary to the demands of the moral order: “We must obey God rather than men” (<em>Acts of the Apostles</em> 5:29)." } },
    { "type": "heading", "level": 4, "id": "besinci-emir-adam-oldurmeyeceksin",
      "tr": "Beşinci Emir: Adam Öldürmeyeceksin",
      "en": "The Fifth Commandment: You Shall not Kill" },
    { "type": "qa", "n": 466, "id": "soru-466", "ccc": "2258–2262, 2318–2320",
      "tr": { "q": "İnsan yaşamına neden saygı gösterilmelidir?",
              "a": "İnsan yaşamına saygı gösterilmelidir, çünkü o <em>kutsaldır</em>. İnsan yaşamı başlangıcından itibaren Tanrı'nın yaratıcı eylemini içerir ve tek amacı olan Yaratıcı ile sonsuza dek özel bir ilişki içinde kalır. Hiç kimsenin masum bir insanı doğrudan yok etmesi meşru değildir. Bu, kişinin onuruna ve Yaratıcı'nın kutsallığına ağır biçimde aykırıdır. “Suçsuzu ve doğruyu öldürme” (Çıkış 23:7)." },
      "en": { "q": "Why must human life be respected?",
              "a": "Human life must be respected because it is <em>sacred</em>. From its beginning human life involves the creative action of God and it remains forever in a special relationship with the Creator, who is its sole end. It is not lawful for anyone directly to destroy an innocent human being. This is gravely contrary to the dignity of the person and the holiness of the Creator. “Do not slay the innocent and the righteous” (<em>Exodus</em> 23:7)." } },
    { "type": "qa", "n": 467, "id": "soru-467", "ccc": "2263–2265",
      "tr": { "q": "Kişilerin ve toplumun meşru savunması bu kurala neden aykırı değildir?",
              "a": "Çünkü kişi meşru olarak kendini savunmayı seçtiğinde yaşam hakkına (ister kendi yaşam hakkı ister bir başkasınınki olsun) saygı gösterir ve öldürmeyi seçmiş olmaz. Gerçekten de bir başkasının yaşamından sorumlu olan kişi için meşru savunma, orantısız güç kullanılmaması koşuluyla, yalnızca bir hak değil, ağır bir görev de olabilir." },
      "en": { "q": "Why is the legitimate defense of persons and of society not opposed to this norm?",
              "a": "Because in choosing to legitimately defend oneself one is respecting the right to life (either one’s own right to life or that of another) and not choosing to kill. Indeed, for someone responsible for the life of another, legitimate defense can be not only a right but a grave duty, provided only that disproportionate force is not used." } },
    { "type": "qa", "n": 468, "id": "soru-468", "ccc": "2266",
      "tr": { "q": "Cezanın amacı nedir?",
              "a": "Meşru kamu otoritesinin verdiği cezanın amacı, suçun yol açtığı düzensizliği gidermek, kamu düzenini ve insanların güvenliğini savunmak ve suçlunun ıslahına katkıda bulunmaktır." },
      "en": { "q": "What is the purpose of punishment?",
              "a": "A punishment imposed by legitimate public authority has the aim of redressing the disorder introduced by the offense, of defending public order and people’s safety, and contributing to the correction of the guilty party." } },
    { "type": "qa", "n": 469, "id": "soru-469", "ccc": "2267",
      "tr": { "q": "Nasıl bir ceza verilebilir?",
              "a": "Verilen ceza suçun ağırlığıyla orantılı olmalıdır. Devletin bugün, suç işlemiş birini zarar veremez hale getirerek suçu etkili biçimde önleme olanakları göz önüne alındığında, suçlunun idamının mutlak bir zorunluluk olduğu durumlar “çok ender, hatta pratikte yok gibidir” (<em>Evangelium Vitae</em>). Öldürücü olmayan araçlar yeterli olduğunda otorite kendini bu araçlarla sınırlamalıdır; çünkü bunlar ortak iyiliğin somut koşullarına daha iyi karşılık gelir, insan kişisinin onuruna daha uygundur ve suçludan kendini düzeltme olanağını kesin olarak almaz." },
      "en": { "q": "What kind of punishment may be imposed?",
              "a": "The punishment imposed must be proportionate to the gravity of the offense. Given the possibilities which the State now has for effectively preventing crime by rendering one who has committed an offense incapable of doing harm, the cases in which the execution of the offender is an absolute necessity “are very rare, if not practically non-existent.” (<em>Evangelium Vitae</em>). When non-lethal means are sufficient, authority should limit itself to such means because they better correspond to the concrete conditions of the common good, are more in conformity with the dignity of the human person, and do not remove definitively from the guilty party the possibility of reforming himself." },
      "note": "Papa Fransiskus 2018'de Katolik Kilisesi'nin İlmihali'nin 2267. maddesini yeniden düzenlemiş ve idam cezasının “kişinin dokunulmazlığına ve onuruna bir saldırı olduğu için kabul edilemez” olduğunu açıklamıştır. Özet'in 2005 tarihli metni burada aslına sadık olarak çevrilmiştir." },
    { "type": "qa", "n": 470, "id": "soru-470", "ccc": "2268–2283, 2321–2326",
      "tr": { "q": "Beşinci emir neyi yasaklar?",
              "a": "Beşinci emir, ahlak yasasına ağır biçimde aykırı olarak şunları yasaklar:\n- <em>doğrudan ve kasıtlı adam öldürmeyi</em> ve buna katılmayı;\n- bir amaç ya da araç olarak istenen <em>doğrudan kürtajı</em> ve buna katılmayı. Bu günaha aforoz cezası bağlanmıştır; çünkü insan varlığı, rahme düştüğü andan itibaren bütünlüğü içinde mutlak olarak saygı görmeli ve korunmalıdır;\n- engellilerin, hastaların ya da ölmek üzere olanların yaşamına bir eylemle ya da gerekli bir eylemin ihmal edilmesiyle son vermekten oluşan <em>doğrudan ötanaziyi</em>;\n- Tanrı'ya, kendine ve komşuya karşı adil sevgiye ağır bir saldırı olduğu ölçüde <em>intiharı</em> ve buna gönüllü olarak katılmayı. Kişinin sorumluluğu verdiği kötü örnek (skandal) nedeniyle ağırlaşabilir; ruhsal olarak rahatsız olan ya da ağır bir korku yaşayan kişinin sorumluluğu azalmış olabilir." },
      "en": { "q": "What is forbidden by the fifth commandment?",
              "a": "The fifth commandment forbids as gravely contrary to the moral law:\n- <em>direct and intentional murder</em> and cooperation in it;\n- <em>direct abortion</em>, willed as an end or as means, as well as cooperation in it. Attached to this sin is the penalty of excommunication because, from the moment of his or her conception, the human being must be absolutely respected and protected in his integrity;\n- <em>direct euthanasia</em> which consists in putting an end to the life of the handicapped, the sick, or those near death by an act or by the omission of a required action;\n- <em>suicide</em> and voluntary cooperation in it, insofar as it is a grave offense against the just love of God, of self, and of neighbor. One’s responsibility may be aggravated by the scandal given; one who is psychologically disturbed or is experiencing grave fear may have diminished responsibility." } },
    { "type": "qa", "n": 471, "id": "soru-471", "ccc": "2278–2279",
      "tr": { "q": "Ölüm yakın görüldüğünde hangi tıbbi uygulamalara izin verilir?",
              "a": "Ölüm yakın görüldüğünde hasta kişiye borçlu olunan olağan bakım meşru olarak kesilemez. Ancak ölümü amaçlamayan ağrı kesicilerin kullanılması ve “aşırı tedavinin”, yani olumlu bir sonuç için makul bir umut olmaksızın orantısız tıbbi uygulamaların kullanılmasının reddedilmesi meşrudur." },
      "en": { "q": "What medical procedures are permitted when death is considered imminent?",
              "a": "When death is considered imminent the ordinary care owed to a sick person cannot be legitimately interrupted. However, it is legitimate to use pain-killers which do not aim at in death and to refuse “over-zealous treatment”, that is the utilization of disproportionate medical procedures without reasonable hope of a positive outcome." } },
    { "type": "qa", "n": 472, "id": "soru-472", "ccc": "2273–2274",
      "tr": { "q": "Toplum neden her embriyoyu korumalıdır?",
              "a": "Her insan bireyinin rahme düşme anından itibaren elinden alınamaz yaşam hakkı, sivil toplumun ve onun yasalarının kurucu bir öğesidir. Devlet gücünü herkesin, özellikle de henüz doğmamış çocuklar dahil en savunmasız olanların haklarının hizmetine sunmadığında, hukuk devletinin temelleri sarsılır." },
      "en": { "q": "Why must society protect every embryo?",
              "a": "The inalienable right to life of every human individual from the first moment of conception is a constitutive element of civil society and its legislation. When the State does not place its power at the service of the rights of all and in particular of the more vulnerable, including unborn children, the very foundations of a State based on law are undermined." } },
    { "type": "qa", "n": 473, "id": "soru-473", "ccc": "2284–2287",
      "tr": { "q": "Kötü örnek olmaktan (skandaldan) nasıl kaçınılır?",
              "a": "Başkalarını kötülük yapmaya yöneltmekten oluşan skandaldan, kişinin canına ve bedenine saygı gösterdiğimizde kaçınılır. Başkalarını bilerek ağır günahlar işlemeye yönelten kişi kendisi de ağır bir suç işlemiş olur." },
      "en": { "q": "How does one avoid scandal?",
              "a": "Scandal, which consists in inducing others to do evil, is avoided when we respect the soul and body of the person. Anyone who deliberately leads others to commit serious sins himself commits a grave offense." } },
    { "type": "qa", "n": 474, "id": "soru-474", "ccc": "2288–2291",
      "tr": { "q": "Bedenimize karşı görevimiz nedir?",
              "a": "Kendi <em>bedensel sağlığımıza</em> ve başkalarınınkine makul bir <em>özen</em> göstermeliyiz; ama <em>beden kültünden</em> ve her türlü aşırılıktan kaçınmalıyız. İnsan sağlığına ve yaşamına çok ciddi zararlar veren uyuşturucuların kullanılmasından ve yiyeceğin, alkolün, tütünün ve ilacın kötüye kullanılmasından da kaçınılmalıdır." },
      "en": { "q": "What duty do we have toward our body?",
              "a": "We must take reasonable <em>care of our own physical health</em> and that of others but avoid the <em>cult of the body</em> and every kind of excess. Also to be avoided are the use of drugs which cause very serious damage to human health and life, as well as the abuse of food, alcohol, tobacco and medicine." } },
    { "type": "qa", "n": 475, "id": "soru-475", "ccc": "2292–2295",
      "tr": { "q": "İnsan bireyleri ya da grupları üzerinde bilimsel, tıbbi ya da psikolojik deneyler ne zaman ahlaken meşrudur?",
              "a": "Kişinin ve toplumun bütünsel iyiliğinin hizmetinde olduklarında, gerektiği gibi bilgilendirilmiş ve rıza göstermiş olması gereken deneklerin yaşamı ve bedensel ve ruhsal bütünlüğü için orantısız riskler taşımadıklarında ahlaken meşrudurlar." },
      "en": { "q": "When are scientific, medical, or psychological experiments on human individuals or groups morally legitimate?",
              "a": "They are morally legitimate when they are at the service of the integral good of the person and of society, without disproportionate risks to the life and physical and psychological integrity of the subjects who must be properly informed and consenting." } },
    { "type": "qa", "n": 476, "id": "soru-476", "ccc": "2296",
      "tr": { "q": "Ölümden önce ve sonra organ nakli ve bağışına izin verilir mi?",
              "a": "Organ nakli, bağışçının rızasıyla ve onun için aşırı riskler olmaksızın ahlaken kabul edilebilir. Ölümden sonra organ bağışının soylu eylemine izin vermeden önce bağışçının gerçekten ölmüş olduğu doğrulanmalıdır." },
      "en": { "q": "Are the transplant and donation of organs allowed before and after death?",
              "a": "The transplant of organs is morally acceptable with the consent of the donor and without excessive risks to him or her. Before allowing the noble act of organ donation after death, one must verify that the donor is truly dead." } },
    { "type": "qa", "n": 477, "id": "soru-477", "ccc": "2297–2298",
      "tr": { "q": "İnsan kişisinin bedensel bütünlüğüne saygıya aykırı uygulamalar nelerdir?",
              "a": "Bunlar şunlardır: adam kaçırma ve rehin alma, terörizm, işkence, şiddet ve doğrudan kısırlaştırma. Bir kişinin uzuvlarının kesilmesi ve sakatlanması ancak kesinlikle tedaviye yönelik tıbbi nedenlerle ahlaken meşrudur." },
      "en": { "q": "What practices are contrary to respect for the bodily integrity of the human person?",
              "a": "They are: kidnapping and hostage taking, terrorism, torture, violence, and direct sterilization. Amputations and mutilations of a person are morally permissible only for strictly therapeutic medical reasons." } },
    { "type": "qa", "n": 478, "id": "soru-478", "ccc": "2299",
      "tr": { "q": "Ölmek üzere olanlara nasıl bir bakım verilmelidir?",
              "a": "Ölmek üzere olanların yeryüzündeki yaşamlarının son anlarını onurla yaşama ve her şeyden önce kendilerini yaşayan Tanrı'yla karşılaşmaya hazırlayan dua ve kutsal sırlarla desteklenme hakkı vardır." },
      "en": { "q": "What care must be given to the dying?",
              "a": "The dying have a right to live the last moments of their earthly lives with dignity and, above all, to be sustained with prayer and the sacraments that prepare them to meet the living God." } },
    { "type": "qa", "n": 479, "id": "soru-479", "ccc": "2300–2301",
      "tr": { "q": "Ölmüşlerin bedenlerine nasıl davranılmalıdır?",
              "a": "Ölmüşlerin bedenlerine sevgi ve saygıyla davranılmalıdır. Bedenin dirilişine imanın inkârını göstermemesi koşuluyla ölünün yakılmasına izin verilir." },
      "en": { "q": "How are the bodies of the deceased to be treated?",
              "a": "The bodies of the departed must be treated with love and respect. Their cremation is permitted provided that it does not demonstrate a denial of faith in the resurrection of the body." } },
    { "type": "qa", "n": 480, "id": "soru-480", "ccc": "2302–2303",
      "tr": { "q": "Rab barış konusunda her insandan ne ister?",
              "a": "Rab, “Ne mutlu barışı sağlayanlara!” (Matta 5:9) diye duyurdu. Yürek barışına çağırdı ve uğranılan bir kötülüğün öcünü alma arzusu olan öfkenin ahlaka aykırılığını kınadı. Komşuya kötülük dilemeye yönelten nefreti de kınadı. Bu tutumlar gönüllü ise ve çok önemli konularda rıza gösterilmişse, sevgiye karşı ölümcül günahlardır." },
      "en": { "q": "What does the Lord ask of every person in regard to peace?",
              "a": "The Lord proclaimed “<em>Blessed</em> are the peacemakers” (<em>Matthew</em> 5:9). He called for peace of heart and denounced the immorality of anger which is a desire for revenge for some evil suffered. He also denounced hatred which leads one to wish evil on one’s neighbor. These attitudes, if voluntary and consented to in matters of great importance, are mortal sins against charity." } },
    { "type": "qa", "n": 481, "id": "soru-481", "ccc": "2304–2305",
      "tr": { "q": "Bu dünyada barış nedir?",
              "a": "İnsan yaşamına saygı ve onun gelişmesi için gerekli olan bu dünyadaki barış, yalnızca savaşın yokluğu ya da düşmanlar arasındaki bir güç dengesi değildir. O, “düzenin huzurudur” ([[Aziz Augustinus|Saint Augustine]]), “adaletin eseridir” (Yeşaya 32:17) ve sevginin sonucudur. Dünyasal barış, Mesih'in barışının sureti ve meyvesidir." },
      "en": { "q": "What is peace in this world?",
              "a": "Peace in this world, which is required for the respect and development of human life, is not simply the absence of war or a balance of power between adversaries. It is “the tranquility of order” (Saint Augustine), “the work of justice” (<em>Isaiah</em> 32:17) and the effect of charity. Earthly peace is the image and fruit of the peace of Christ." } },
    { "type": "qa", "n": 482, "id": "soru-482", "ccc": "2304, 2307–2308",
      "tr": { "q": "Dünyasal barış için ne gereklidir?",
              "a": "Dünyasal barış, kişilerin nimetlerinin eşit dağılımını ve korunmasını, insanlar arasında özgür iletişimi, kişilerin ve halkların onuruna saygıyı ve adaletin ve kardeşliğin gayretle uygulanmasını gerektirir." },
      "en": { "q": "What is required for earthly peace?",
              "a": "Earthly peace requires the equal distribution and safeguarding of the goods of persons, free communication among human beings, respect for the dignity of persons and peoples, and the assiduous practice of justice and fraternity." } },
    { "type": "qa", "n": 483, "id": "soru-483", "ccc": "2307–2310",
      "tr": { "q": "Askeri güç kullanmak ne zaman ahlaken meşrudur?",
              "a": "Askeri güç kullanımı, aşağıdaki koşullar aynı anda bulunduğunda ahlaken haklıdır:\n- saldırganın verdiği zarar kalıcı, ağır ve kesin olmalıdır;\n- diğer bütün barışçıl araçların etkisiz olduğu görülmüş olmalıdır;\n- sağlam temellere dayanan başarı olasılıkları bulunmalıdır;\n- silah kullanımı, özellikle modern kitle imha silahlarının gücü göz önüne alındığında, ortadan kaldırılacak kötülükten daha ağır kötülükler doğurmamalıdır." },
      "en": { "q": "When is it morally permitted to use military force?",
              "a": "The use of military force is morally justified when the following conditions are simultaneously present:\n- the suffering inflicted by the aggressor must be lasting, grave and certain;\n- all other peaceful means must have been shown to be ineffective;\n- there are well founded prospects of success;\n- the use of arms, especially given the power of modern weapons of mass destruction, must not produce evils graver than the evil to be eliminated." } },
    { "type": "qa", "n": 484, "id": "soru-484", "ccc": "2309",
      "tr": { "q": "Savaş tehlikesinde bu koşulların titizlikle değerlendirilmesinin sorumluluğu kime aittir?",
              "a": "Bu sorumluluk, yurttaşlara ulusal savunma yükümlülüğü getirme hakkına da sahip olan hükümet yetkililerinin sağduyulu yargısına aittir. Kişisel vicdani ret hakkı bu yükümlülüğe bir istisna oluşturur; bu durumda yükümlülük insan topluluğuna başka bir hizmet biçimiyle yerine getirilmelidir." },
      "en": { "q": "In danger of war, who has the responsibility for the rigorous evaluation of these conditions?",
              "a": "This responsibility belongs to the prudential judgment of government officials who also have the right to impose on citizens the obligation of national defense. The personal right to conscientious objection makes an exception to this obligation which should then be carried out by another form of service to the human community." } },
    { "type": "qa", "n": 485, "id": "soru-485", "ccc": "2312–2314, 2328",
      "tr": { "q": "Savaş durumunda ahlak yasası ne gerektirir?",
              "a": "Savaş sırasında bile ahlak yasası her zaman geçerli kalır. Sivillere, yaralı askerlere ve savaş esirlerine insanca davranılmasını gerektirir. Uluslar hukukuna aykırı bilinçli eylemler ve bu tür eylemleri buyuran emirler suçtur ve körü körüne itaat bunları mazur göstermez. Kitlesel yıkım eylemleri ve aynı şekilde halkların ya da etnik azınlıkların yok edilmesi en ağır günahlar olarak kınanmalıdır. Kişi bu tür eylemleri buyuran emirlere direnmekle ahlaken yükümlüdür." },
      "en": { "q": "In case of war, what does the moral law require?",
              "a": "Even during a war the moral law always remains valid. It requires the humane treatment of noncombatants, wounded soldiers and prisoners of war. Deliberate actions contrary to the law of nations, and the orders that command such actions are crimes, which blind obedience does not excuse. Acts of mass destruction must be condemned and likewise the extermination of peoples or ethnic minorities, which are most grievous sins. One is morally bound to resist the orders that command such acts." } },
    { "type": "qa", "n": 486, "id": "soru-486", "ccc": "2315–2317, 2327–2330",
      "tr": { "q": "Savaştan kaçınmak için ne yapılmalıdır?",
              "a": "Her savaşın beraberinde getirdiği kötülükler ve adaletsizlikler nedeniyle, ondan kaçınmak için makul olarak mümkün olan her şeyi yapmalıyız. Bu amaçla özellikle şunlardan kaçınmak önemlidir: meşru otoritelerce denetlenmeyen silah birikimi ve satışı; her türlü ekonomik ve toplumsal adaletsizlik; etnik ve dinsel ayrımcılık; kıskançlık, güvensizlik, gurur ve intikam ruhu. Bunları ve diğer düzensizlikleri aşmak için yapılan her şey barışın inşasına ve savaştan kaçınmaya katkıda bulunur." },
      "en": { "q": "What must be done to avoid war?",
              "a": "Because of the evils and injustices that all war brings with it, we must do everything reasonably possible to avoid it. To this end it is particularly important to avoid: the accumulation and sale of arms which are not regulated by the legitimate authorities; all forms of economic and social injustice; ethnic and religious discrimination; envy, mistrust, pride and the spirit of revenge. Everything done to overcome these and other disorders contributes to building up peace and avoiding war." } },
    { "type": "heading", "level": 4, "id": "altinci-emir-zina-etmeyeceksin",
      "tr": "Altıncı Emir: Zina Etmeyeceksin",
      "en": "The Sixth Commandment: You Shall not Commit Adultery" },
    { "type": "qa", "n": 487, "id": "soru-487", "ccc": "2331–2336, 2392–2393",
      "tr": { "q": "İnsanların kendi cinsel kimlikleriyle ilgili sorumluluğu nedir?",
              "a": "Tanrı insanları kişisel onurda eşit olan erkek ve kadın olarak yarattı ve onları bir sevgi ve birlik çağrısına çağırdı. Herkes erkek ya da kadın olarak kimliğini kabul etmeli, bu kimliğin kişinin bütünü için önemini, özgüllüğünü ve tamamlayıcılığını tanımalıdır." },
      "en": { "q": "What responsibility do human persons have in regard to their own sexual identity?",
              "a": "God has created human beings as male and female, equal in personal dignity, and has called them to a vocation of love and of communion. Everyone should accept his or her identity as male or female, recognizing its importance for the whole of the person, its specificity and complementarity." } },
    { "type": "qa", "n": 488, "id": "soru-488", "ccc": "2337–2338",
      "tr": { "q": "İffet nedir?",
              "a": "İffet, cinselliğin kişi içinde olumlu bir biçimde bütünleşmesi demektir. Cinsellik, bir kişinin bir başka kişiyle ilişkisine doğru bir biçimde bütünleştiğinde gerçekten insani olur. İffet ahlaki bir erdem, Tanrı'nın bir armağanı, bir lütuf ve Kutsal Ruh'un bir meyvesidir." },
      "en": { "q": "What is chastity?",
              "a": "Chastity means the positive integration of sexuality within the person. Sexuality becomes truly human when it is integrated in a correct way into the relationship of one person to another. Chastity is a moral virtue, a gift of God, a grace, and a fruit of the Holy Spirit." } },
    { "type": "qa", "n": 489, "id": "soru-489", "ccc": "2339–2341",
      "tr": { "q": "İffet erdemi neleri içerir?",
              "a": "İffet erdemi, kendini vermeye yönelik insan özgürlüğünün bir ifadesi olarak kendine hâkim olmada bir çıraklığı içerir. Bu amaca ulaşmak için aşamalı olarak gerçekleşen bütünsel ve sürekli bir eğitim gereklidir." },
      "en": { "q": "What is involved in the virtue of chastity?",
              "a": "The virtue of chastity involves an apprenticeship in self-mastery as an expression of human freedom directed towards self-giving. An integral and continuing formation, which is brought about in stages, is necessary to achieve this goal." } },
    { "type": "qa", "n": 490, "id": "soru-490", "ccc": "2340–2347",
      "tr": { "q": "İffetin yaşanmasına yardım eden araçlar nelerdir?",
              "a": "Kişinin kullanabileceği birçok araç vardır: Tanrı'nın lütfu, kutsal sırların yardımı, dua, kendini tanıma, çeşitli durumlara uyarlanmış bir çilecilik uygulaması, ahlaki erdemlerin, özellikle tutkuların akıl tarafından yönlendirilmesini amaçlayan ölçülülük erdeminin uygulanması." },
      "en": { "q": "What are the means that aid the living of chastity?",
              "a": "There are many means at one's disposal: the grace of God, the help of the sacraments, prayer, self-knowledge, the practice of an asceticism adapted to various situations, the exercise of the moral virtues, especially the virtue of temperance which seeks to have the passions guided by reason." } },
    { "type": "qa", "n": 491, "id": "soru-491", "ccc": "2348–2350, 2394",
      "tr": { "q": "Herkes iffeti hangi biçimde yaşamaya çağrılmıştır?",
              "a": "Bütün iffetin örneği olan Mesih'in izleyicileri olarak bütün vaftiz edilmişler, kendi özel yaşam durumlarına uygun olarak iffetli yaşamaya çağrılmıştır. Bazıları, kendilerini bölünmemiş bir yürekle yalnızca Tanrı'ya olağanüstü bir biçimde vermelerini sağlayan bekâreti ya da adanmış bekârlığı ikrar ederler. Diğerleri ise evliyseler evlilik iffeti içinde yaşarlar ya da evli değillerse perhiz içinde iffeti uygularlar." },
      "en": { "q": "In what way is everyone called to live chastity?",
              "a": "As followers of Christ, the model of all chastity, all the baptised are called to live chastely in keeping with their particular states of life. Some profess virginity or consecrated celibacy which enables them to give themselves to God alone with an undivided heart in a remarkable manner. Others, if they are married live in conjugal chastity, or if unmarried practise chastity in continence." } },
    { "type": "qa", "n": 492, "id": "soru-492", "ccc": "2351–2359, 2396",
      "tr": { "q": "İffete karşı başlıca günahlar nelerdir?",
              "a": "İffete karşı ağır günahlar nesnelerine göre farklılık gösterir: zina, mastürbasyon, evlilik dışı cinsel ilişki, pornografi, fuhuş, tecavüz ve eşcinsel eylemler. Bu günahlar şehvet kusurunun ifadeleridir. Bu tür eylemler reşit olmayanların bedensel ve ahlaki bütünlüğüne karşı işlendiğinde daha da ağırlaşır." },
      "en": { "q": "What are the principal sins against chastity?",
              "a": "Grave sins against chastity differ according to their object: adultery, masturbation, fornication, pornography, prostitution, rape, and homosexual acts. These sins are expressions of the vice of lust. These kinds of acts committed against the physical and moral integrity of minors become even more grave." } },
    { "type": "qa", "n": 493, "id": "soru-493", "ccc": "2336",
      "tr": { "q": "Yalnızca “zina etmeyeceksin” dese de altıncı emir neden iffete karşı bütün günahları yasaklar?",
              "a": "Dekalog'un Kutsal Kitap metni “zina etmeyeceksin” (Çıkış 20:14) dese de Kilise Geleneği Eski ve Yeni Antlaşma'nın ahlaki öğretilerini bütünlüklü olarak izler ve altıncı emri iffete karşı bütün günahları kapsayan bir emir olarak kabul eder." },
      "en": { "q": "Although it says only “you shall not commit adultery” why does the sixth commandment forbid all sins against chastity?",
              "a": "Although the biblical text of the Decalogue reads “you shall not commit adultery” (<em>Exodus</em> 20:14), the Tradition of the Church comprehensively follows the moral teachings of the Old and New Testaments and considers the sixth commandment as encompassing all sins against chastity." } },
    { "type": "qa", "n": 494, "id": "soru-494", "ccc": "2354",
      "tr": { "q": "Sivil otoritenin iffet konusundaki sorumluluğu nedir?",
              "a": "Kişinin onuruna saygıyı geliştirmekle yükümlü olduğu ölçüde sivil otorite, iffetin uygulanmasına elverişli bir ortam yaratmaya çalışmalıdır. Ayrıca, özellikle reşit olmayanları ve toplumun en zayıf üyelerini korumak için, yukarıda sözü edilen iffete karşı ağır suçların yayılmasını önleyecek uygun yasalar çıkarmalıdır." },
      "en": { "q": "What is the responsibility of civil authority in regard to chastity?",
              "a": "Insofar as it is bound to promote respect for the dignity of the person, civil authority should seek to create an environment conducive to the practice of chastity. It should also enact suitable legislation to prevent the spread of the grave offenses against chastity mentioned above, especially in order to protect minors and those who are the weakest members of society." } },
    { "type": "qa", "n": 495, "id": "soru-495", "ccc": "2360–2361, 2397–2398",
      "tr": { "q": "Cinselliğin yöneldiği evlilik sevgisinin nimetleri nelerdir?",
              "a": "Vaftiz edilmişler için Evlilik sırrıyla kutsanmış olan evlilik sevgisinin nimetleri birlik, sadakat, çözülmezlik ve yaşamın doğurulmasına açıklıktır." },
      "en": { "q": "What are the goods of conjugal love to which sexuality is ordered?",
              "a": "The goods of conjugal love, which for those who are baptized is sanctified by the sacrament of Matrimony, are unity, fidelity, indissolubility, and an openness to the procreation of life." } },
    { "type": "qa", "n": 496, "id": "soru-496", "ccc": "2362–2367",
      "tr": { "q": "Evlilik eyleminin anlamı nedir?",
              "a": "Evlilik eyleminin iki yönlü bir anlamı vardır: birleştirici (eşlerin karşılıklı olarak kendilerini vermesi) ve doğurucu (yaşamın aktarılmasına açıklık). Hiç kimse Tanrı'nın evlilik eyleminin bu iki anlamı arasında kurduğu ayrılmaz bağı, bunlardan birini ya da diğerini dışlayarak koparamaz." },
      "en": { "q": "What is the meaning of the conjugal act?",
              "a": "The conjugal act has a twofold meaning: unitive (the mutual self-giving of the spouses) and procreative (an openness to the transmission of life). No one may break the inseparable connection which God has established between these two meanings of the conjugal act by excluding one or the other of them." } },
    { "type": "qa", "n": 497, "id": "soru-497", "ccc": "2368–2369, 2399",
      "tr": { "q": "Doğumların düzenlenmesi ne zaman ahlakidir?",
              "a": "Sorumlu babalığın ve anneliğin bir yönü olan doğumların düzenlenmesi, eşler tarafından dış baskı olmaksızın sürdürüldüğünde; bencillikten değil ciddi nedenlerle uygulandığında; ve ahlakın nesnel ölçütlerine uygun yöntemlerle, yani dönemsel perhiz ve kısır dönemlerin kullanılmasıyla yapıldığında nesnel olarak ahlaken kabul edilebilir." },
      "en": { "q": "When is it moral to regulate births?",
              "a": "The regulation of births, which is an aspect of responsible fatherhood and motherhood, is objectively morally acceptable when it is pursued by the spouses without external pressure; when it is practiced not out of selfishness but for serious reasons; and with methods that conform to the objective criteria of morality, that is, periodic continence and use of the infertile periods." } },
    { "type": "qa", "n": 498, "id": "soru-498", "ccc": "2370–2372",
      "tr": { "q": "Doğum kontrolünün ahlaka aykırı araçları nelerdir?",
              "a": "Doğurmayı engellemeyi (ister evlilik eyleminden önce, ister eylemin gerçekleşmesi sırasında, ister doğal sonuçlarının gelişimi sırasında) bir amaç ya da araç olarak öngören her eylem –örneğin doğrudan kısırlaştırma ya da doğum kontrolü (kontrasepsiyon)– özünde ahlaka aykırıdır." },
      "en": { "q": "What are immoral means of birth control?",
              "a": "Every action - for example, direct sterilization or contraception - is intrinsically immoral which (either in anticipation of the conjugal act, in its accomplishment or in the development of its natural consequences) proposes, as an end or as a means, to hinder procreation." } },
    { "type": "qa", "n": 499, "id": "soru-499", "ccc": "2373–2377",
      "tr": { "q": "Yapay tohumlama ve yapay döllenme neden ahlaka aykırıdır?",
              "a": "Ahlaka aykırıdırlar; çünkü doğurmayı eşlerin kendilerini birbirlerine verdikleri eylemden ayırırlar ve böylece insan kişisinin kökeni ve yazgısı üzerinde teknolojinin egemenliğini başlatırlar. Ayrıca, evli çift dışında bir kişiyi işin içine katan tekniklerin kullanıldığı heterolog tohumlama ve döllenme, çocuğun, kendisinin tanıdığı, birbirine evlilikle bağlı ve yalnızca birbirleri aracılığıyla anne baba olma konusunda tek hakka sahip bir baba ve anneden doğma hakkını çiğner." },
      "en": { "q": "Why are artificial insemination and artificial fertilization immoral?",
              "a": "They are immoral because they dissociate procreation from the act with which the spouses give themselves to each other and so introduce the domination of technology over the origin and destiny of the human person. Furthermore, heterologous insemination and fertilization with the use of techniques that involve a person other than the married couple infringe upon the right of a child to be born of a father and mother known to him, bound to each other by marriage and having the exclusive right to become parents only through each another." } },
    { "type": "qa", "n": 500, "id": "soru-500", "ccc": "2378",
      "tr": { "q": "Çocuklar nasıl değerlendirilmelidir?",
              "a": "Çocuk <em>Tanrı'nın bir armağanıdır</em>, evliliğin en yüce armağanıdır. Çocuk sahibi olma hakkı diye bir şey yoktur (örneğin “ne pahasına olursa olsun bir çocuk”). Ama çocuğun anne babasının evlilik eyleminin meyvesi olma hakkı ve rahme düştüğü andan itibaren bir kişi olarak saygı görme hakkı vardır." },
      "en": { "q": "How should children be considered?",
              "a": "A child is a <em>gift of God</em>, the supreme gift of marriage. There is no such thing as a right to have children (e.g. “a child at any cost”). But a child does have the right to be the fruit of the conjugal act of its parents as well as the right to be respected as a person from the moment of conception." } },
    { "type": "qa", "n": 501, "id": "soru-501", "ccc": "2379",
      "tr": { "q": "Çocukları olmayan eşler ne yapabilir?",
              "a": "Bütün meşru tıbbi seçenekleri tükettikten sonra çocuk armağanı kendilerine verilmezse, eşler koruyucu ailelik ya da evlat edinme yoluyla veya başkalarına anlamlı hizmetlerde bulunarak cömertliklerini gösterebilirler. Böylece değerli bir ruhsal verimliliği gerçekleştirirler." },
      "en": { "q": "What can spouses do when they do not have children?",
              "a": "Should the gift of a child not be given to them, after exhausting all legitimate medical options, spouses can show their generosity by way of foster care or adoption or by performing meaningful services for others. In this way they realize a precious spiritual fruitfulness." } },
    { "type": "qa", "n": 502, "id": "soru-502", "ccc": "2380–2391, 2400",
      "tr": { "q": "Evliliğin onuruna karşı işlenen suçlar nelerdir?",
              "a": "Bunlar şunlardır: zina, boşanma, çok eşlilik, ensest, serbest birliktelikler (evlilik dışı birlikte yaşama, metreslik) ve evlilikten önce ya da evlilik dışında cinsel eylemler." },
      "en": { "q": "What are the offenses against the dignity of marriage?",
              "a": "These are: adultery, divorce, polygamy, incest, free unions (cohabitation, concubinage), and sexual acts before or outside of marriage." } },
    { "type": "heading", "level": 4, "id": "yedinci-emir-calmayacaksin",
      "tr": "Yedinci Emir: Çalmayacaksın",
      "en": "The Seventh Commandment: You Shall not Steal" },
    { "type": "qa", "n": 503, "id": "soru-503", "ccc": "2401–2402",
      "tr": { "q": "Yedinci emir neyi ortaya koyar?",
              "a": "Yedinci emir, nimetlerin evrensel amacına ve dağılımına ve onlar üzerindeki özel mülkiyete saygıyı, ayrıca kişilere, onların mülkiyetine ve yaratılışın bütünlüğüne saygıyı gerektirir. Kilise bu Buyrukta, ekonomik, toplumsal ve siyasal yaşamda doğru davranış biçimini, insan emeğinin hakkını ve görevini, uluslar arasında adaleti ve dayanışmayı ve yoksullara sevgiyi içeren toplumsal öğretisinin temelini de bulur." },
      "en": { "q": "What is set forth by the seventh commandment?",
              "a": "The seventh commandment requires respect for the universal destination and distribution of goods and the private ownership of them, as well as respect for persons, their property, and the integrity of creation. The Church also finds in this Commandment the basis for her social doctrine which involves the correct way of acting in economic, social and political life, the right and the duty of human labor, justice and solidarity among nations, and love for the poor." } },
    { "type": "qa", "n": 504, "id": "soru-504", "ccc": "2403",
      "tr": { "q": "Özel mülkiyet hakkı hangi koşullarda vardır?",
              "a": "Özel mülkiyet hakkı, mülkiyetin adil bir yolla edinilmiş ya da alınmış olması ve herkesin temel ihtiyaçlarının karşılanması için nimetlerin evrensel amacının öncelik taşıması koşuluyla vardır." },
      "en": { "q": "Under what conditions does the right to private property exist?",
              "a": "The right to private property exists provided the property is acquired or received in a just way and that the universal destination of goods for the satisfaction of the basic needs of all takes precedence." } },
    { "type": "qa", "n": 505, "id": "soru-505", "ccc": "2404–2406",
      "tr": { "q": "Özel mülkiyetin amacı nedir?",
              "a": "Özel mülkiyetin amacı, bireylerin kendi sorumlulukları altındakilerin ve ihtiyaç içindeki diğer kişilerin temel ihtiyaçlarını karşılamalarına yardım ederek onların özgürlüğünü ve onurunu güvence altına almaktır." },
      "en": { "q": "What is the purpose of private property?",
              "a": "The purpose of private property is to guarantee the freedom and dignity of individual persons by helping them to meet the basic needs of those in their charge and also of others who are in need." } },
    { "type": "qa", "n": 506, "id": "soru-506", "ccc": "2407, 2450–2451",
      "tr": { "q": "Yedinci emir neyi gerektirir?",
              "a": "Yedinci emir, adaletin ve sevginin, ölçülülüğün ve dayanışmanın uygulanması yoluyla başkalarının mallarına saygıyı gerektirir. Özellikle <em>verilen sözlere ve yapılan sözleşmelere saygıyı</em>, işlenen <em>adaletsizliğin onarılmasını</em> ve çalınan malların geri verilmesini, ayrıca soyu tükenme tehlikesindeki türlere özel bir dikkat gösterilerek evrenin maden, bitki ve hayvan kaynaklarının sağduyulu ve ölçülü kullanımıyla <em>yaratılışın bütünlüğüne</em> saygıyı gerektirir." },
      "en": { "q": "What does the seventh commandment require?",
              "a": "The seventh commandment requires respect for the goods of others through the practice of justice and charity, temperance and solidarity. In particular it requires <em>respect for promises made and contracts agreed to</em>, <em>reparation for injustice</em> committed and restitution of stolen goods, and respect for the <em>integrity of creation</em> by the prudent and moderate use of the mineral, vegetable, and animal resources of the universe with special attention to those species which are in danger of extinction." } },
    { "type": "qa", "n": 507, "id": "soru-507", "ccc": "2416–2418, 2457",
      "tr": { "q": "İnsanlar hayvanlara karşı nasıl bir tutum takınmalıdır?",
              "a": "İnsanlar hayvanlara Tanrı'nın yaratıkları olarak iyilikle davranmalı; hem onlara aşırı sevgiden hem de özellikle makul sınırları aşan ve hayvanlara gereksiz acı veren bilimsel deneylerle onların gelişigüzel kullanılmasından kaçınmalıdır." },
      "en": { "q": "What attitude should people have toward animals?",
              "a": "People must treat animals with kindness as creatures of God and avoid both excessive love for them and an indiscriminate use of them especially by scientific experiments that go beyond reasonable limits and entail needless suffering for the animals." } },
    { "type": "qa", "n": 508, "id": "soru-508", "ccc": "2408–2413, 2453–2455",
      "tr": { "q": "Yedinci emir neyi yasaklar?",
              "a": "Her şeyden önce yedinci emir, başkasının malını sahibinin makul iradesine karşı almak ya da kullanmak olan hırsızlığı yasaklar. Bu, adil olmayan ücretler ödeyerek; başkalarının zararına çıkar sağlamak için malların değeri üzerinde spekülasyon yaparak; ya da çek veya fatura sahteciliğiyle de yapılabilir. Vergi kaçırma ya da ticari dolandırıcılık; özel ya da kamu mülküne kasıtlı olarak zarar verme; tefecilik; yolsuzluk; ortak malların özel çıkar için kötüye kullanılması; bilerek kötü yapılan iş ve israf da yasaktır." },
      "en": { "q": "What is forbidden by the seventh commandment?",
              "a": "Above all, the seventh commandment forbids theft, which is the taking or using of another’s property against the reasonable will of the owner. This can be done also by paying unjust wages; by speculation on the value of goods in order to gain an advantage to the detriment of others; or by the forgery of checks or invoices. Also forbidden is tax evasion or business fraud; willfully damaging private or public property; usury; corruption; the private abuse of common goods; work deliberately done poorly; and waste." } },
    { "type": "qa", "n": 509, "id": "soru-509", "ccc": "2419–2423",
      "tr": { "q": "Kilise'nin toplumsal öğretisinin içeriği nedir?",
              "a": "Kilise'nin toplumsal öğretisi, insan kişisinin onuru ve toplumsal boyutu hakkındaki Müjde gerçeğinin organik bir gelişimidir; düşünme için ilkeler, yargı için ölçütler ve eylem için kurallar ve yönergeler sunar." },
      "en": { "q": "What is the content of the social doctrine of the Church?",
              "a": "The social doctrine of the Church is an organic development of the truth of the Gospel about the dignity of the human person and his social dimension offering principles for reflection, criteria for judgment, and norms and guidelines for action." } },
    { "type": "qa", "n": 510, "id": "soru-510", "ccc": "2420, 2458",
      "tr": { "q": "Kilise toplumsal alanlara ne zaman müdahale eder?",
              "a": "Kilise, kişinin temel hakları, ortak iyilik ya da ruhların kurtuluşu gerektirdiğinde ekonomik ve toplumsal konular hakkında ahlaki bir yargıda bulunarak müdahale eder." },
      "en": { "q": "When does the Church intervene in social areas?",
              "a": "The Church intervenes by making a moral judgment about economic and social matters when the fundamental rights of the person, the common good, or the salvation of souls requires it." } },
    { "type": "qa", "n": 511, "id": "soru-511", "ccc": "2459",
      "tr": { "q": "Toplumsal ve ekonomik yaşam nasıl sürdürülmelidir?",
              "a": "Ahlak düzeninin alanı içinde, kendine özgü yöntemlerine göre, toplumsal adalete uygun olarak bütün insanın ve bütün insan topluluğunun hizmetinde sürdürülmelidir. Toplumsal ve ekonomik yaşamın yaratıcısı, merkezi ve amacı insan kişisi olmalıdır." },
      "en": { "q": "How should social and economic life be pursued?",
              "a": "It should be pursued according to its own proper methods within the sphere of the moral order, at the service of the whole human being and of the entire human community in keeping with social justice. Social and economic life should have the human person as its author, center, and goal." } },
    { "type": "qa", "n": 512, "id": "soru-512", "ccc": "2424–2425",
      "tr": { "q": "Kilise'nin toplumsal öğretisine ne aykırı olur?",
              "a": "Kişilerin temel haklarını feda eden ya da kârı tek kuralları veya nihai amaçları yapan ekonomik ve toplumsal sistemler Kilise'nin toplumsal öğretisine aykırıdır. Bu nedenle Kilise, modern zamanlarda Komünizmle ya da sosyalizmin ateist ve totaliter biçimleriyle ilişkilendirilen ideolojileri reddeder. Ancak Kilise kapitalizmin uygulanmasında da bencil bireyciliği ve piyasa yasalarının insan emeği üzerinde mutlak üstünlüğünü reddeder." },
      "en": { "q": "What would be opposed to the social doctrine of the Church?",
              "a": "Opposed to the social doctrine of the Church are economic and social systems that sacrifice the basic rights of persons or that make profit their exclusive norm or ultimate end. For this reason the Church rejects the ideologies associated in modern times with Communism or with atheistic and totalitarian forms of socialism. But in the practice of capitalism the Church also rejects self centered individualism and an absolute primacy of the laws of the marketplace over human labor." } },
    { "type": "qa", "n": 513, "id": "soru-513", "ccc": "2426–2428, 2460–2461",
      "tr": { "q": "Çalışmanın anlamı nedir?",
              "a": "Çalışma, insanların Yaratıcı Tanrı ile işbirliği yaptığı hem bir görev hem de bir haktır. Gerçekten de bağlılıkla ve yetkinlikle çalışarak doğamıza yazılmış olan potansiyeli gerçekleştirir, Yaratıcı'nın armağanlarını ve O'ndan aldığımız yetenekleri onurlandırır, kendimizin ve ailelerimizin geçimini sağlar ve insan topluluğuna hizmet ederiz. Ayrıca Tanrı'nın lütfuyla çalışma, kutsallaşmanın ve başkalarının kurtuluşu için Mesih'le işbirliğinin bir aracı olabilir." },
      "en": { "q": "What is the meaning of work?",
              "a": "Work is both a duty and a right through which human beings collaborate with God the Creator. Indeed, by working with commitment and competence we fulfil the potential inscribed in our nature, honor the Creator’s gifts and the talents received from him, provide for ourselves and for our families, and serve the human community. Furthermore, by the grace of God, work can be a means of sanctification and collaboration with Christ for the salvation of others." } },
    { "type": "qa", "n": 514, "id": "soru-514", "ccc": "2429, 2433–2434",
      "tr": { "q": "Her insanın ne tür bir çalışmaya hakkı vardır?",
              "a": "Güvenli ve onurlu bir işe erişim, haksız ayrımcılık olmaksızın ve özgür ekonomik girişime ve adil ücrete saygı gösterilerek herkese açık olmalıdır." },
      "en": { "q": "To what type of work does every person have a right?",
              "a": "Access to secure and honest employment must be open to all without unjust discrimination and with respect for free economic initiative and fair compensation." } },
    { "type": "qa", "n": 515, "id": "soru-515", "ccc": "2431",
      "tr": { "q": "Devletin çalışmayla ilgili sorumluluğu nedir?",
              "a": "Bireysel özgürlüğü ve özel mülkiyeti, ayrıca istikrarlı bir para birimini ve etkin kamu hizmetlerini güvence altına almak Devletin görevidir. Ekonomik alanda insan haklarının kullanılmasını denetlemek ve yönlendirmek de Devletin sorumluluğudur. Koşullara göre toplum, yurttaşların iş bulmasına yardım etmelidir." },
      "en": { "q": "What responsibility does the State have in regard to labor?",
              "a": "It is the role of the State to guarantee individual freedom and private property, as well as a stable currency and efficient public services. It is also the State’s responsibility to oversee and direct the exercise of human rights in the economic sector. According to circumstances, society must help citizens to find work." } },
    { "type": "qa", "n": 516, "id": "soru-516", "ccc": "2432",
      "tr": { "q": "İşletme yönetiminin görevi nedir?",
              "a": "İşletme yöneticileri faaliyetlerinin ekonomik ve ekolojik etkilerinden sorumludur. Kâr, yatırımları, işletmenin geleceğini, istihdamı ve ekonomik yaşamın sağlıklı gelişimini güvence altına almak için gerekli olsa da yalnızca kârın artmasını değil, kişilerin iyiliğini de göz önünde bulundurmalıdırlar." },
      "en": { "q": "What is the task of business management?",
              "a": "Business managers are responsible for the economic and ecological effects of their operations. They must consider the good of persons and not only the increase of profits, even though profits are necessary to assure investments, the future of the business, employment, and the good progress of economic life." } },
    { "type": "qa", "n": 517, "id": "soru-517", "ccc": "2435",
      "tr": { "q": "Çalışanların görevleri nelerdir?",
              "a": "İşlerini vicdanlı bir biçimde, yetkinlik ve özveriyle yerine getirmeli, anlaşmazlıkları diyalogla çözmeye çalışmalıdırlar. Şiddet içermeyen bir greve başvurmak, orantılı bir yarar elde etmek için gerekli yol olarak göründüğünde ve ortak iyiliği hesaba kattığında ahlaken meşrudur." },
      "en": { "q": "What are the duties of workers?",
              "a": "They must carry out their work in a conscientious way with competence and dedication, seeking to resolve any controversies with dialogue. Recourse to a non-violent strike is morally legitimate when it appears to be the necessary way to obtain a proportionate benefit and it takes into account the common good." } },
    { "type": "qa", "n": 518, "id": "soru-518", "ccc": "2437–2441",
      "tr": { "q": "Uluslar arasında adalet ve dayanışma nasıl sağlanır?",
              "a": "Uluslararası düzeyde bütün uluslar ve kurumlar, yoksulluğu, kaynakların ve ekonomik potansiyelin eşitsizliğini, ekonomik ve toplumsal adaletsizlikleri, kişilerin sömürülmesini, yoksul ülkelerin borç birikimini ve daha az gelişmiş ülkelerin kalkınmasını engelleyen sapkın mekanizmaları ortadan kaldırmak ya da en azından azaltmak amacıyla çalışmalarını dayanışma ve yerellik içinde yürütmelidir." },
      "en": { "q": "How is justice and solidarity among nations brought about?",
              "a": "On the international level, all nations and institutions must carry out their work in solidarity and subsidiarity for the purpose of eliminating or at least reducing poverty, the inequality of resources and economic potential, economic and social injustices, the exploitation of persons, the accumulation of debts by poor countries, and the perverse mechanisms that impede the development of the less advanced countries." } },
    { "type": "qa", "n": 519, "id": "soru-519", "ccc": "2442",
      "tr": { "q": "Hristiyanlar siyasal ve toplumsal yaşama nasıl katılırlar?",
              "a": "Halktan inanlılar, dünyasal gerçeklikleri Hristiyan ruhuyla canlandırarak ve Müjde'nin sahih tanıkları ve barış ve adaletin etkin öğeleri olarak herkesle işbirliği yaparak siyasal ve toplumsal yaşama doğrudan katılırlar." },
      "en": { "q": "In what way do Christians participate in political and social life?",
              "a": "The lay faithful take part directly in political and social life by animating temporal realities with a Christian spirit and collaborating with all as authentic witnesses of the Gospel and agents of peace and justice." } },
    { "type": "qa", "n": 520, "id": "soru-520", "ccc": "2443–2449, 2462–2463",
      "tr": { "q": "Yoksullara sevgi neyle esinlenir?",
              "a": "Yoksullara sevgi, Mutluluk Çağrıları'nın Müjdesi'nden ve İsa'nın yoksullara gösterdiği sürekli ilgi örneğinden esinlenir. İsa şöyle dedi: “Bu en önemsiz kardeşlerimden biri için ne yaptınızsa, benim için yapmış oldunuz” (Matta 25:40). Yoksullara sevgi, maddi yoksulluğa ve ayrıca kültürel, ahlaki ve dinsel yoksulluğun pek çok biçimine karşı mücadeleyle kendini gösterir. Ruhsal ve bedensel merhamet işleri ve yüzyıllar boyunca kurulan pek çok hayır kurumu, İsa'nın öğrencilerini belirginleştiren, yoksullara yönelik öncelikli sevginin somut bir tanıklığıdır." },
      "en": { "q": "By what is love for the poor inspired?",
              "a": "Love for the poor is inspired by the Gospel of the Beatitudes and by the example of Jesus in his constant concern for the poor. Jesus said, “Whatever you have done to the least of my brethren, you have done to me” (<em>Matthew</em> 25:40). Love for the poor shows itself through the struggle against material poverty and also against the many forms of cultural, moral, and religious poverty. The spiritual and corporal works of mercy and the many charitable institutions formed throughout the centuries are a concrete witness to the preferential love for the poor which characterizes the disciples of Jesus." } },
    { "type": "heading", "level": 4, "id": "sekizinci-emir-komsuna-karsi-yalan-yere-taniklik",
      "tr": "Sekizinci Emir: Komşuna Karşı Yalan Yere Tanıklık Etmeyeceksin",
      "en": "The Eighth Commandment: You Shall not Bear False Witness against your Neighbor" },
    { "type": "qa", "n": 521, "id": "soru-521", "ccc": "2464–2470, 2504",
      "tr": { "q": "Kişinin gerçeğe karşı görevi nedir?",
              "a": "Her insan eylemlerinde ve sözlerinde içtenliğe ve doğruluğa çağrılmıştır. Herkesin gerçeği arama, ona bağlanma ve bütün yaşamını onun gereklerine göre düzenleme görevi vardır. İsa Mesih'te Tanrı'nın bütün gerçeği açıkça görünür olmuştur. O “<em>gerçektir</em>”. O'nu izleyenler gerçeğin Ruhu'nda yaşar ve ikiyüzlülükten, gizlemekten ve riyakârlıktan sakınırlar." },
      "en": { "q": "What is one’s duty toward the truth?",
              "a": "Every person is called to sincerity and truthfulness in acting and speaking. Everyone has the duty to seek the truth, to adhere to it and to order one’s whole life in accordance with its demands. In Jesus Christ the whole of God’s truth has been made manifest. He is “<em>the truth</em>”. Those who follow him live in the Spirit of truth and guard against duplicity, dissimulation, and hypocrisy." } },
    { "type": "qa", "n": 522, "id": "soru-522", "ccc": "2471–2474, 2505–2506",
      "tr": { "q": "Gerçeğe nasıl tanıklık edilir?",
              "a": "Bir Hristiyan, hem kamusal hem de özel her etkinlik alanında ve gerekirse yaşamını feda ederek Müjde'nin gerçeğine tanıklık etmelidir. Şehitlik, imanın gerçeğine verilen en yüce tanıklıktır." },
      "en": { "q": "How does one bear witness to the truth?",
              "a": "A Christian must bear witness to the truth of the Gospel in every field of his activity, both public and private, and also if necessary, with the sacrifice of his very life. Martyrdom is the supreme witness given to the truth of the faith." } },
    { "type": "qa", "n": 523, "id": "soru-523", "ccc": "2475–2487, 2507–2509",
      "tr": { "q": "Sekizinci emir neyi yasaklar?",
              "a": "Sekizinci emir şunları yasaklar:\n- ağırlığı, çarpıttığı gerçeğe, koşullara, yalan söyleyenin niyetlerine ve kurbanlarının uğradığı zarara göre ölçülen <em>yalan tanıklığı</em>, <em>yalan yere yemini</em> ve <em>yalanı</em>;\n- her insanın hakkı olan iyi şöhreti ve onuru azaltan ya da yok eden <em>aceleci yargıyı</em>, <em>dedikoduyu</em>, <em>karalamayı</em> ve <em>iftirayı</em>;\n- özellikle ağır günahlara ya da meşru olmayan çıkarlar elde etmeye yönelikse <em>dalkavukluğu</em>, <em>yağcılığı</em> ya da <em>yaranmacılığı</em>.\nGerçeğe karşı işlenen bir günah, başkalarına zarar vermişse onarım gerektirir." },
      "en": { "q": "What is forbidden by the eighth commandment?",
              "a": "The eighth commandment forbids:\n- <em>false witness</em>, <em>perjury</em>, and <em>lying</em>, the gravity of which is measured by the truth it deforms, the circumstances, the intentions of the one who lies, and the harm suffered by its victims;\n- <em>rash judgment</em>, <em>slander</em>, <em>defamation</em> and <em>calumny</em> which diminish or destroy the good reputation and honor to which every person has a right;\n- <em>flattery</em>, <em>adulation</em>, or <em>complaisance</em>, especially if directed to serious sins or toward the achievement of illicit advantages.\nA sin committed against truth demands reparation if it has caused harm to others." } },
    { "type": "qa", "n": 524, "id": "soru-524", "ccc": "2488–2492, 2510–2511",
      "tr": { "q": "Sekizinci emir neyi gerektirir?",
              "a": "Sekizinci emir, kişisel ve ortak iyiliğin, özel yaşamın korunmasının ve skandal tehlikesinin hep birlikte göz önünde bulundurulması gereken <em>iletişim</em> ve <em>bilgi aktarımı</em> alanında sevginin ölçülülüğüyle birlikte gerçeğe saygıyı; ağır ve orantılı nedenlerle istisnai durumlar dışında korunması gereken <em>meslek sırlarına</em> saygıyı; ve ayrıca gizlilik mührü altında verilen <em>sırlara</em> saygıyı gerektirir." },
      "en": { "q": "What is required by the eighth commandment?",
              "a": "The eighth commandment requires respect for the truth accompanied by the discretion of charity in the field of <em>communication </em>and the<em> imparting of information</em>, where the personal and common good, the protection of privacy and the danger of scandal must all be taken into account; in respecting <em>professional secrets</em> which must be kept, save in exceptional cases for grave and proportionate reasons; and also in respecting <em>confidences</em> given under the seal of secrecy." } },
    { "type": "qa", "n": 525, "id": "soru-525", "ccc": "2493–2499, 2512",
      "tr": { "q": "Toplumsal iletişim araçları nasıl kullanılmalıdır?",
              "a": "Medyanın sağladığı bilgi ortak iyiliğin hizmetinde olmalıdır. İçeriği doğru ve –adaletin ve sevginin sınırları içinde– eksiksiz olmalıdır. Ayrıca bilgi, ahlak yasalarına ve kişinin meşru haklarına ve onuruna titiz bir saygıyla, dürüstçe ve uygun biçimde iletilmelidir." },
      "en": { "q": "How is one to use the means of social communication?",
              "a": "The information provided by the media must be at the service of the common good. Its content must be true and – within the limits of justice and charity – also complete. Furthermore, information must be communicated honestly and properly with scrupulous respect for moral laws and the legitimate rights and dignity of the person." } },
    { "type": "qa", "n": 526, "id": "soru-526", "ccc": "2500–2503, 2513",
      "tr": { "q": "Gerçek, güzellik ve kutsal sanat arasında nasıl bir ilişki vardır?",
              "a": "Gerçek güzeldir; kendi içinde ruhsal güzelliğin parıltısını taşır. Gerçeğin sözlerle ifade edilmesinin yanı sıra, gerçeğin başka tamamlayıcı ifadeleri de vardır; özellikle sanat eserlerinin güzelliğinde. Bunlar hem Tanrı'nın verdiği yeteneklerin hem de insan çabasının meyvesidir. <em>Kutsal sanat</em>, gerçek ve güzel olarak, Mesih'te görünür kılınan Tanrı'nın gizemini çağrıştırmalı ve yüceltmeli ve Gerçeğin ve Sevginin aşkın, görünmez Güzelliği olan Yaratıcı ve Kurtarıcı Tanrı'ya tapınmaya ve O'nu sevmeye yöneltmelidir." },
      "en": { "q": "What relationship exists between truth, beauty and sacred art?",
              "a": "The truth is beautiful, carrying in itself the splendour of spiritual beauty. In addition to the expression of the truth in words there are other complementary expressions of the truth, most specifically in the beauty of artistic works. These are the fruit both of talents given by God and of human effort. <em> Sacred art</em> by being true and beautiful should evoke and glorify the mystery of God made visible in Christ, and lead to the adoration and love of God, the Creator and Savior, who is the surpassing, invisible Beauty of Truth and Love." } },
    { "type": "heading", "level": 4, "id": "dokuzuncu-emir-komsunun-karisina-goz-dikmeyeceksin",
      "tr": "Dokuzuncu Emir: Komşunun Karısına Göz Dikmeyeceksin",
      "en": "The Ninth Commandment: You Shall not Covet your Neighbor's Wife" },
    { "type": "qa", "n": 527, "id": "soru-527", "ccc": "2514–2516, 2528–2530",
      "tr": { "q": "Dokuzuncu emir neyi gerektirir?",
              "a": "Dokuzuncu emir, düşüncede ve arzuda bedensel şehvet eğiliminin yenilmesini gerektirir. Bu eğilime karşı mücadele, yüreği arındırmayı ve ölçülülük erdemini uygulamayı içerir." },
      "en": { "q": "What is required by the ninth commandment?",
              "a": "The ninth commandment requires that one overcome carnal concupiscence in thought and in desire. The struggle against such concupiscence entails purifying the heart and practicing the virtue of temperance." } },
    { "type": "qa", "n": 528, "id": "soru-528", "ccc": "2517–2519, 2531–2532",
      "tr": { "q": "Dokuzuncu emir neyi yasaklar?",
              "a": "Dokuzuncu emir, altıncı emrin yasakladığı eylemlerle bağlantılı düşünceleri ve arzuları beslemeyi yasaklar." },
      "en": { "q": "What is forbidden by the ninth commandment?",
              "a": "The ninth commandment forbids cultivating thoughts and desires connected to actions forbidden by the sixth commandment." } },
    { "type": "qa", "n": 529, "id": "soru-529", "ccc": "2520",
      "tr": { "q": "Yürek temizliğine nasıl ulaşılır?",
              "a": "Düzensiz arzulara karşı savaşta vaftiz edilmiş kişi, Tanrı'nın lütfuyla, iffet erdemi ve armağanı, niyet temizliği, (hem dış hem de iç) bakış temizliği, hayal gücünün ve duyguların disiplini ve dua aracılığıyla yürek temizliğine ulaşabilir." },
      "en": { "q": "How does one reach purity of heart?",
              "a": "In the battle against disordered desires the baptised person is able, by the grace of God, to achieve purity of heart through the virtue and gift of chastity, through purity of intention, purity of vision (both exterior and interior), discipline of the imagination and of feelings and by prayer." } },
    { "type": "qa", "n": 530, "id": "soru-530", "ccc": "2521–2527, 2533",
      "tr": { "q": "Temizliğin diğer gereklilikleri nelerdir?",
              "a": "Temizlik, kişinin içsel merkezini korurken iffetin inceliğini ifade eden <em>edebi</em> (hayâyı) gerektirir. Edep, kişinin başkalarına nasıl baktığını ve onlara nasıl davrandığını, kişilerin onuruna ve birliğine uygun olarak yönlendirir. Temizlik kişiyi yaygın erotizmden kurtarır ve sağlıksız merakı besleyen şeylerden uzak tutar. Temizlik ayrıca, insan özgürlüğüne ilişkin yanlış bir anlayışa dayanan ahlaki gevşekliğe karşı sürekli bir mücadele yoluyla <em>toplumsal ortamın arındırılmasını</em> da gerektirir." },
      "en": { "q": "What are the other requirements for purity?",
              "a": "Purity requires <em>modesty</em> which, while protecting the intimate center of the person, expresses the sensitivity of chastity. It guides how one looks at others and behaves toward them in conformity with the dignity of persons and their communion. Purity frees one from wide-spread eroticism and avoids those things which foster morbid curiosity. Purity also requires a <em>purification of the social climate</em> by means of a constant struggle against moral permissiveness which is founded on an erroneous conception of human freedom." } },
    { "type": "heading", "level": 4, "id": "onuncu-emir-komsunun-malina-goz-dikmeyeceksin",
      "tr": "Onuncu Emir: Komşunun Malına Göz Dikmeyeceksin",
      "en": "The Tenth Commandment: You Shall not Covet your Neighbor’s Possessions" },
    { "type": "qa", "n": 531, "id": "soru-531", "ccc": "2534–2540, 2551–2554",
      "tr": { "q": "Onuncu emir neyi gerektirir ve neyi yasaklar?",
              "a": "Önceki emri tamamlayan bu emir, başkalarının mülkiyetine karşı içsel bir saygı tutumunu gerektirir ve <em>açgözlülüğü</em>, başkalarının mallarına duyulan <em>dizginsiz hırsı</em> ve başkasının nimetlerini görünce duyulan üzüntü ve onları kendisi için ölçüsüzce elde etme arzusu olan <em>kıskançlığı</em> yasaklar." },
      "en": { "q": "What is required and what is forbidden by the tenth commandment?",
              "a": "This commandment, which completes the preceding commandment, requires an interior attitude of respect for the property of others and forbids <em>greed</em>, <em>unbridled covetousness</em> for the goods of others, and <em>envy</em> which is the sadness one experiences at the sight of another’s goods and the immoderate desire to acquire them for oneself." } },
    { "type": "qa", "n": 532, "id": "soru-532", "ccc": "2544–2547, 2556",
      "tr": { "q": "İsa ruhta yoksulluk konusunda neye çağırır?",
              "a": "İsa öğrencilerini Kendisini her şeye ve herkese yeğlemeye çağırır. İncil'e dayalı yoksulluk ruhu içinde zenginliklerden el çekmek ve tanrısal takdire teslim olmak, bizi gelecekle ilgili kaygıdan kurtarır ve bizi “ruhta yoksul olanların mutluluğuna, çünkü Göklerin Egemenliği onlarındır” (Matta 5:3) hazırlar." },
      "en": { "q": "What does Jesus call for in poverty of spirit?",
              "a": "Jesus calls his disciples to prefer him to everything and everyone. Detachment from riches – in the spirit of evangelical poverty – and self-abandonment to divine providence free us from anxiety about the future and prepare us for the blessedness of the “poor in spirit, for theirs is the kingdom of heaven” (<em>Mathew</em> 5:3)." } },
    { "type": "qa", "n": 533, "id": "soru-533", "ccc": "2548–2550, 2557",
      "tr": { "q": "İnsanın en büyük arzusu nedir?",
              "a": "İnsan kişisinin en büyük arzusu Tanrı'yı görmektir. “Tanrı'yı görmek istiyorum” bütün varlığımızın haykırışıdır. Gerçek ve tam mutluluğumuzu, bizi sevgiyle yaratan ve sonsuz bir sevgiyle Kendine çeken Kişi'yi görmede ve O'nun mutluluğunda gerçekleştiririz." },
      "en": { "q": "What is the greatest human desire?",
              "a": "The greatest desire of the human person is to see God. “I want to see God” is the cry of our whole being. We realize our true and full happiness in the vision and beatitude of the One who created us out of love and draws us to himself with infinite love." } },
    { "type": "quote",
      "tr": "“Tanrı'yı gören, düşünebileceği bütün nimetlere kavuşmuştur.” ([[Nyssalı Aziz Gregorios|Saint Gregory of Nyssa]])",
      "en": "“Whoever sees God has obtained all the goods of which he can conceive.” (Saint Gregory of Nyssa)" }
  ]
}/*JSON-END*/;
